<img src="https://api.mehewara.edu.lk/api/v1/media/legacy/supabase-storage/a97c6cf9-2a62-5393-84d3-d3b9390a1aef.unknown" alt="Screenshot 2026-06-17 230150.png" class="mhw-q-img" />', NULL, 'The reaction is a single displacement (or replacement) reaction because one element ($M$) displaces another element ($Zn$) from its compound.', 'The reaction is a single displacement (or replacement) reaction because one element ($M$) displaces another element ($Zn$) from its compound.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
