INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('441a5d07-5966-4981-a259-9ea6527acb22', 'b1d149e5-524a-5910-810d-ac25ea4a94f7', 'ඇතුළතට සහ පිටතට සෛල නිපදවයි.', 'ඇතුළතට සහ පිටතට සෛල නිපදවයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7b218b6f-60d5-4718-b5b4-8d960e3e51f9', 'b1d149e5-524a-5910-810d-ac25ea4a94f7', 'මෘදුස්තර සෛල වලින් සමන්විත වේ.', 'මෘදුස්තර සෛල වලින් සමන්විත වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('17607257-6dd7-4ef8-8f08-4e4c7658733e', 'b1d149e5-524a-5910-810d-ac25ea4a94f7', 'විභේදනය නොවූ සෛලවලින් සමන්විත වේ.', 'විභේදනය නොවූ සෛලවලින් සමන්විත වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('12794bca-8a3d-402e-b1bc-9d253ea5e032', 'b1d149e5-524a-5910-810d-ac25ea4a94f7', 'කඳේ ප්‍රාථමික සහ ද්විතීයික වර්ධනයට දායක වේ.', 'කඳේ ප්‍රාථමික සහ ද්විතීයික වර්ධනයට දායක වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('47db928d-deca-500e-806d-84d794ef90d1', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 15, '<p>ජලයේ ද්‍රාව්‍ය ද්‍රවණය වීම</p>', '<p>ජලයේ ද්‍රාව්‍ය ද්‍රවණය වීම</p>', NULL, 'පිරිසිදු ජලයේ ජල විභවය ($\Psi$) සහ ද්‍රාව්‍ය විභවය ($\Psi_s$) ශුන්‍ය වේ. ජලයට ද්‍රාව්‍ය (solutes) එකතු කළ විට, නිදහස් ජල අණු ප්‍රමාණය අඩුවන බැවින් ජල විභවය සෘණ අගයක් ගනී (එනම් අඩු වේ). එසේම ද්‍රාව්‍ය විභවය ද වඩාත් සෘණ අගයක් ගන්නා බැවින් එය ද අඩු වේ.', 'පිරිසිදු ජලයේ ජල විභවය ($\Psi$) සහ ද්‍රාව්‍ය විභවය ($\Psi_s$) ශුන්‍ය වේ. ජලයට ද්‍රාව්‍ය (solutes) එකතු කළ විට, නිදහස් ජල අණු ප්‍රමාණය අඩුවන බැවින් ජල විභවය සෘණ අගයක් ගනී (එනම් අඩු වේ). එසේම ද්‍රාව්‍ය විභවය ද වඩාත් සෘණ අගයක් ගන්නා බැවින් එය ද අඩු වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
