INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a674639b-09bb-4c4a-a889-f82f0865461b', '47db928d-deca-500e-806d-84d794ef90d1', 'ජල විභවය අඩු කරන අතර ද්‍රාව්‍ය විභවය වැඩි කරයි.', 'ජල විභවය අඩු කරන අතර ද්‍රාව්‍ය විභවය වැඩි කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8276e3fd-5d1e-40f7-8111-f123b7c34972', '47db928d-deca-500e-806d-84d794ef90d1', 'ජල විභවය වැඩි කරන අතර ද්‍රාව්‍ය විභවය අඩු කරයි.', 'ජල විභවය වැඩි කරන අතර ද්‍රාව්‍ය විභවය අඩු කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fb48203b-5a72-461c-ab14-c160a9e6bc13', '47db928d-deca-500e-806d-84d794ef90d1', 'ජල විභවය සහ ද්‍රාව්‍ය විභවය කෙරෙහි එකිනෙකට ස්වාධීන ලෙස බලපායි.', 'ජල විභවය සහ ද්‍රාව්‍ය විභවය කෙරෙහි එකිනෙකට ස්වාධීන ලෙස බලපායි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8aea0720-f2e4-502b-beb9-68769c918be3', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 16, '<p>ආස්‍රැතිය</p>', '<p>ආස්‍රැතිය</p>', NULL, 'ආස්‍රැතිය (Osmosis) යනු වරණීය පාරගම්‍ය පටලයක් හරහා වැඩි ජල විභවයක සිට අඩු ජල විභවයකට ජලය ගමන් කිරීමයි. පසෙහි ජල විභවය මූල කේශවල ජල විභවයට වඩා වැඩි බැවින්, පසේ සිට මූල කේශ තුළට ජලය ඇතුළු වන්නේ ආස්‍රැතිය මගිනි. එය අක්‍රිය (ශක්තිය වැය නොවන) ක්‍රියාවලියකි.', 'ආස්‍රැතිය (Osmosis) යනු වරණීය පාරගම්‍ය පටලයක් හරහා වැඩි ජල විභවයක සිට අඩු ජල විභවයකට ජලය ගමන් කිරීමයි. පසෙහි ජල විභවය මූල කේශවල ජල විභවයට වඩා වැඩි බැවින්, පසේ සිට මූල කේශ තුළට ජලය ඇතුළු වන්නේ ආස්‍රැතිය මගිනි. එය අක්‍රිය (ශක්තිය වැය නොවන) ක්‍රියාවලියකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9ac3750c-fc9c-4ecc-b9d0-65c3e49337a2', '8aea0720-f2e4-502b-beb9-68769c918be3', 'පාරගම්‍ය පටලයක් තුළින් ජල අණු විසරණය වීම නිසා සිදු වේ.', 'පාරගම්‍ය පටලයක් තුළින් ජල අණු විසරණය වීම නිසා සිදු වේ.', NULL, 'sanitized', 'v1', 0, 1);
