INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2de66856-70c9-4683-9b53-7f5117ff31a1', '8aea0720-f2e4-502b-beb9-68769c918be3', 'පසේ සිට මූල කේශ තුළට ජලය ඇතුළු වන යන්ත්‍රණයයි.', 'පසේ සිට මූල කේශ තුළට ජලය ඇතුළු වන යන්ත්‍රණයයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f40ddc7a-a926-4f5a-8634-ecc9716b3e5c', '8aea0720-f2e4-502b-beb9-68769c918be3', 'ප්‍රභවයේදී පෙනේර නල ඒකක තුළ පීඩනය අඩු කරයි.', 'ප්‍රභවයේදී පෙනේර නල ඒකක තුළ පීඩනය අඩු කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a6319e16-d6e7-5001-96a3-33e7246ae07e', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 17, '<p>මේරූ පත්‍රවල හරිතක්ෂය ඇති විය හැක්කේ පහත සඳහන් කුමන මූල ද්‍රව්‍යවල ඌනතාව නිසාද?</p>', '<p>මේරූ පත්‍රවල හරිතක්ෂය ඇති විය හැක්කේ පහත සඳහන් කුමන මූල ද්‍රව්‍යවල ඌනතාව නිසාද?</p>', NULL, 'ශාකයක් තුළ පහසුවෙන් සංක්‍රමණය විය හැකි මූලද්‍රව්‍ය (mobile elements) වල ඌනතා ලක්ෂණ මුලින්ම දිස්වන්නේ මේරූ පත්‍ර වලය. මැග්නීසියම් (Mg) සහ නයිට්‍රජන් (N) වල ඌනතාවය නිසා මේරූ පත්‍රවල හරිතක්ෂය (chlorosis) ඇති වේ.', 'ශාකයක් තුළ පහසුවෙන් සංක්‍රමණය විය හැකි මූලද්‍රව්‍ය (mobile elements) වල ඌනතා ලක්ෂණ මුලින්ම දිස්වන්නේ මේරූ පත්‍ර වලය. මැග්නීසියම් (Mg) සහ නයිට්‍රජන් (N) වල ඌනතාවය නිසා මේරූ පත්‍රවල හරිතක්ෂය (chlorosis) ඇති වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
