INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3d290686-e706-4c28-ac13-5ed317a2c0b0', '91c30fc2-0bb0-5b8d-96a3-93e27b5eade9', 'අනුමස්තිෂ්කය - පහර දීමේ හෝ පලා යාමේ ප්‍රතිචාරය ආරම්භ කිරීම', 'අනුමස්තිෂ්කය - පහර දීමේ හෝ පලා යාමේ ප්‍රතිචාරය ආරම්භ කිරීම', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0a13a168-48c8-500c-894f-d2da24dcf30f', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 26, '<p>මිනිස් ඇසේ දෘෂ්ටි විතානයේ සෛල ස්තර රුධිරග්‍රාහියේ සිට කාච රසය දෙසට සකස් වී ඇත්තේ පිළිවෙළින්</p>', '<p>මිනිස් ඇසේ දෘෂ්ටි විතානයේ සෛල ස්තර රුධිරග්‍රාහියේ සිට කාච රසය දෙසට සකස් වී ඇත්තේ පිළිවෙළින්</p>', NULL, 'දෘෂ්ටි විතානයේ වඩාත්ම පිටතින් (රුධිර ග්‍රාහිය දෙසින්) ඇත්තේ වර්ණක අපිච්ඡද ස්තරයයි. ඉන්පසු පිළිවෙලින් ප්‍රකාශ ප්‍රතිග්‍රාහක සෛල (යෂ්ටි හා කේතු), ද්විධ්‍රැව සෛල සහ කාච රසය දෙසට වන්නට ගැංග්ලියා සෛල පිහිටයි. එබැවින් නිවැරදි පිළිතුර 5 වේ.', 'දෘෂ්ටි විතානයේ වඩාත්ම පිටතින් (රුධිර ග්‍රාහිය දෙසින්) ඇත්තේ වර්ණක අපිච්ඡද ස්තරයයි. ඉන්පසු පිළිවෙලින් ප්‍රකාශ ප්‍රතිග්‍රාහක සෛල (යෂ්ටි හා කේතු), ද්විධ්‍රැව සෛල සහ කාච රසය දෙසට වන්නට ගැංග්ලියා සෛල පිහිටයි. එබැවින් නිවැරදි පිළිතුර 5 වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3ef08b3e-9585-4f08-bf9c-2f7fa9e8f0b0', '0a13a168-48c8-500c-894f-d2da24dcf30f', 'අපිච්ඡද ස්තරය, ද්විධ්‍රැව සෛල, ගැංග්ලියා සෛල සහ ප්‍රකාශ ප්‍රතිග්‍රාහක ලෙස ය.', 'අපිච්ඡද ස්තරය, ද්විධ්‍රැව සෛල, ගැංග්ලියා සෛල සහ ප්‍රකාශ ප්‍රතිග්‍රාහක ලෙස ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('60e65d5c-bb1b-41d9-a20c-81598598eda2', '0a13a168-48c8-500c-894f-d2da24dcf30f', 'ප්‍රකාශ ප්‍රතිග්‍රාහක, අපිච්ඡද ස්තරය, ගැංග්ලියා සෛල සහ ද්විධ්‍රැව සෛල ලෙස ය.', 'ප්‍රකාශ ප්‍රතිග්‍රාහක, අපිච්ඡද ස්තරය, ගැංග්ලියා සෛල සහ ද්විධ්‍රැව සෛල ලෙස ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f9799be5-4d19-4e30-a37a-993d9c6b564c', '0a13a168-48c8-500c-894f-d2da24dcf30f', 'අපිච්ඡද ස්තරය, ද්වීධ්‍රැව සෛල, ප්‍රකාශ ප්‍රතිග්‍රාහක සහ ගැංග්ලියා සෛල ලෙසය.', 'අපිච්ඡද ස්තරය, ද්වීධ්‍රැව සෛල, ප්‍රකාශ ප්‍රතිග්‍රාහක සහ ගැංග්ලියා සෛල ලෙසය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3463ce97-da4a-4cdb-a63c-9c8fb22ead07', '0a13a168-48c8-500c-894f-d2da24dcf30f', 'ගැංග්ලියා සෛල, ද්විධ්‍රැව සෛල, ප්‍රකාශ ප්‍රතිග්‍රාහක සහ අපිච්ඡද ස්තරය ලෙස ය.', 'ගැංග්ලියා සෛල, ද්විධ්‍රැව සෛල, ප්‍රකාශ ප්‍රතිග්‍රාහක සහ අපිච්ඡද ස්තරය ලෙස ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7afe6d3c-153f-4048-9ee7-ffdfa18bbdd3', '0a13a168-48c8-500c-894f-d2da24dcf30f', 'අපිච්ඡද ස්තරය, ප්‍රකාශ ප්‍රතිග්‍රාහක, ද්විධ්‍රැව සෛල සහ ගැංග්ලියා සෛල ලෙස ය.', 'අපිච්ඡද ස්තරය, ප්‍රකාශ ප්‍රතිග්‍රාහක, ද්විධ්‍රැව සෛල සහ ගැංග්ලියා සෛල ලෙස ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('918ee99d-cd68-5b42-8563-b7541f6f749a', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 27, '<p>මිනිසාගේ ස්වයංසාධක ස්නායු පද්ධතියේ අනුවේගී කොටස උත්තේජනය වීම නිසා</p>', '<p>මිනිසාගේ ස්වයංසාධක ස්නායු පද්ධතියේ අනුවේගී කොටස උත්තේජනය වීම නිසා</p>', NULL, 'අනුවේගී ස්නායු පද්ධතිය (Sympathetic nervous system) ''පහරදීමේ හෝ පලායාමේ'' ප්‍රතිචාර සඳහා දේහය සූදානම් කරයි. මෙහිදී ශුක්‍ර මුදා හැරීම (ejaculation) උත්තේජනය වේ. හෘත් ස්පන්දනය වැඩි වීම, කණීනිකාව විස්තාරණය වීම සහ ජීර්ණය/මුත්‍ර පහ කිරීම නිෂේධනය වීම මෙහි අනිත් ක්‍රියාකාරකම් වේ.', 'අනුවේගී ස්නායු පද්ධතිය (Sympathetic nervous system) ''පහරදීමේ හෝ පලායාමේ'' ප්‍රතිචාර සඳහා දේහය සූදානම් කරයි. මෙහිදී ශුක්‍ර මුදා හැරීම (ejaculation) උත්තේජනය වේ. හෘත් ස්පන්දනය වැඩි වීම, කණීනිකාව විස්තාරණය වීම සහ ජීර්ණය/මුත්‍ර පහ කිරීම නිෂේධනය වීම මෙහි අනිත් ක්‍රියාකාරකම් වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('88b4c68d-a87e-49e0-b4a1-8f26d50f45a9', '918ee99d-cd68-5b42-8563-b7541f6f749a', 'හෘත් ස්පන්දන වේගය අඩු වේ.', 'හෘත් ස්පන්දන වේගය අඩු වේ.', NULL, 'sanitized', 'v1', 0, 1);
