INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3c0932d5-3eb9-4f59-b8a7-938d97ea718f', '918ee99d-cd68-5b42-8563-b7541f6f749a', 'ඇසේ කණීනිකාව සංකෝචනය වේ.', 'ඇසේ කණීනිකාව සංකෝචනය වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('45d3e259-0e57-48d4-baed-e228dea70962', '918ee99d-cd68-5b42-8563-b7541f6f749a', 'මුත්‍ර පහ කිරීම උත්තේජනය වේ.', 'මුත්‍ර පහ කිරීම උත්තේජනය වේ.', NULL, 'sanitized', 'v1', 3, 0);
