INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c644fdc3-75f0-4d60-9ed1-3a04ddf8ae5f', 'bfad8cba-3930-5699-9fcf-8e3c0257eada', 'වෙනස් වන පරිසර තුළ විශේෂ පරිණාමය වීම එමගින් තහවුරු කෙරේ.', 'වෙනස් වන පරිසර තුළ විශේෂ පරිණාමය වීම එමගින් තහවුරු කෙරේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('169f0e85-6f33-4776-926e-b32a68fe3bfa', 'bfad8cba-3930-5699-9fcf-8e3c0257eada', 'තනි ජනකයෙකුගෙන් ජීවීන් ශීඝ්‍ර ලෙස ගුණනය වීම සඳහා එය දායක වේ.', 'තනි ජනකයෙකුගෙන් ජීවීන් ශීඝ්‍ර ලෙස ගුණනය වීම සඳහා එය දායක වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('75d64bbf-68eb-4aa2-9c55-29e0b3cfaa74', 'bfad8cba-3930-5699-9fcf-8e3c0257eada', 'සංසේචනය වීමකින් තොරව ශුක්‍රාණුවකින් නව ජීවීන් විකසනය විය හැකි ය.', 'සංසේචනය වීමකින් තොරව ශුක්‍රාණුවකින් නව ජීවීන් විකසනය විය හැකි ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e0302591-8ce1-5357-8720-035c9bc27279', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 30, '<p>මානව හිස් කබලේ</p>', '<p>මානව හිස් කබලේ</p>', NULL, 'ඌර්ධව හනුක අස්ථිය (Maxilla) සහ ලලාටාස්ථිය (Frontal bone) වාතයෙන් පිරුණු කුහර හෙවත් කෝටරක (sinuses) දරයි. ජිද්‍රාස්ථිය (Ethmoid) හා කිලාස්ථිය (Sphenoid) කපාල අස්ථි වන අතර, හලාස්ථිය (Vomer) වක්ත්‍ර අස්ථියකි. යුග වක්‍රය තැනීමට යුග අස්ථිය සහ ශංඛක අස්ථිය දායක වේ.', 'ඌර්ධව හනුක අස්ථිය (Maxilla) සහ ලලාටාස්ථිය (Frontal bone) වාතයෙන් පිරුණු කුහර හෙවත් කෝටරක (sinuses) දරයි. ජිද්‍රාස්ථිය (Ethmoid) හා කිලාස්ථිය (Sphenoid) කපාල අස්ථි වන අතර, හලාස්ථිය (Vomer) වක්ත්‍ර අස්ථියකි. යුග වක්‍රය තැනීමට යුග අස්ථිය සහ ශංඛක අස්ථිය දායක වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
