INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4f7e3694-0cd6-445f-a1d3-a7a2ae57f83b', 'e0302591-8ce1-5357-8720-035c9bc27279', 'අධෝහනුවේ චුචුකාකාර ප්‍රසරය ශංඛක අස්ථිය සමග සන්ධානය වේ.', 'අධෝහනුවේ චුචුකාකාර ප්‍රසරය ශංඛක අස්ථිය සමග සන්ධානය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('69e24f23-62ca-400f-8cae-c1c9239093c7', 'e0302591-8ce1-5357-8720-035c9bc27279', 'ඌර්ධව හනුක අස්ථිය සහ ලලාටාස්ථිය කෝටරක දරයි.', 'ඌර්ධව හනුක අස්ථිය සහ ලලාටාස්ථිය කෝටරක දරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e4c10a46-374f-5dfa-b545-233e5b2399de', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 31, '<p>දෙමුහුම් දිරිය</p>', '<p>දෙමුහුම් දිරිය</p>', NULL, 'නිවැරදි පිළිතුර 3 වේ. දෙමුහුම් දිරිය (Hybrid vigor හෙවත් heterosis) යනු දෙමාපියන්ට වඩා දෙමුහුම් ජනිතයා තුළ යහපත් ලක්ෂණ ප්‍රකාශ වීමයි. මෙය ඇතිවන්නේ විෂම යුග්මකතාව (heterozygosity) වැඩි වීම නිසා අහිතකර නිලීන ඇලීල වල බලපෑම යටපත් වීමෙනි.', 'නිවැරදි පිළිතුර 3 වේ. දෙමුහුම් දිරිය (Hybrid vigor හෙවත් heterosis) යනු දෙමාපියන්ට වඩා දෙමුහුම් ජනිතයා තුළ යහපත් ලක්ෂණ ප්‍රකාශ වීමයි. මෙය ඇතිවන්නේ විෂම යුග්මකතාව (heterozygosity) වැඩි වීම නිසා අහිතකර නිලීන ඇලීල වල බලපෑම යටපත් වීමෙනි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('09a5fea5-93a3-435d-a7db-123282fb0c04', 'e4c10a46-374f-5dfa-b545-233e5b2399de', 'ප්‍රවේණික ව සමාන ජීවීන් අතර අභිජනනයෙන් වැඩි කර ගත හැකිය.', 'ප්‍රවේණික ව සමාන ජීවීන් අතර අභිජනනයෙන් වැඩි කර ගත හැකිය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bc450357-312b-488b-9f87-a83105d00f02', 'e4c10a46-374f-5dfa-b545-233e5b2399de', 'F පරම්පරාවට වඩා දෙමව්පියන්ගේ වැඩිය.', 'F පරම්පරාවට වඩා දෙමව්පියන්ගේ වැඩිය.', NULL, 'sanitized', 'v1', 1, 0);
