INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0d7a22c2-b984-4776-836b-ff1dd2232d30', 'e4c10a46-374f-5dfa-b545-233e5b2399de', 'දෙමුහුම් අතර අභිජනනයෙන් පවත්වා ගත හැකිය.', 'දෙමුහුම් අතර අභිජනනයෙන් පවත්වා ගත හැකිය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('23ba4fb1-9430-49c3-b410-ba4f0823aee1', 'e4c10a46-374f-5dfa-b545-233e5b2399de', 'අන්තර් විශේෂ දෙමුහුම් කරණයේ ප්‍රතිඵලයකි.', 'අන්තර් විශේෂ දෙමුහුම් කරණයේ ප්‍රතිඵලයකි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2a4a599c-9121-5a0f-8d56-e8d7171a70a9', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 32, '<p>ටොපොඅයිසොමරේස්වල කෘත්‍යයක් වන්නේ</p>', '<p>ටොපොඅයිසොමරේස්වල කෘත්‍යයක් වන්නේ</p>', NULL, 'නිවැරදි පිළිතුර 4 වේ. DNA ප්‍රතිවලිත වීමේදී හෙලිකේස් එන්සයිමය මගින් DNA දඟරය ලිහන විට ඊට ඉදිරියෙන් ඇති දාම වල අධික ලෙස ඇඹරීම නිසා ඇතිවන ආතතිය (strain) සමනය කරන්නේ ටොපොඅයිසොමරේස් (Topoisomerase) එන්සයිමය මගිනි.', 'නිවැරදි පිළිතුර 4 වේ. DNA ප්‍රතිවලිත වීමේදී හෙලිකේස් එන්සයිමය මගින් DNA දඟරය ලිහන විට ඊට ඉදිරියෙන් ඇති දාම වල අධික ලෙස ඇඹරීම නිසා ඇතිවන ආතතිය (strain) සමනය කරන්නේ ටොපොඅයිසොමරේස් (Topoisomerase) එන්සයිමය මගිනි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b40b01c2-402a-4fcd-b80f-c8954dd2a819', '2a4a599c-9121-5a0f-8d56-e8d7171a70a9', 'DNA දාමයේ හිදැස් මුද්‍රා තැබීමයි.', 'DNA දාමයේ හිදැස් මුද්‍රා තැබීමයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bfb4afa8-9ab3-4847-8f1c-22dfe56dfcb1', '2a4a599c-9121-5a0f-8d56-e8d7171a70a9', 'DNA ද්විත්ව දාමයේ දඟර ලිහීමයි.', 'DNA ද්විත්ව දාමයේ දඟර ලිහීමයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6ea1127c-386e-48a6-99fe-b0f9bd2b8ab4', '2a4a599c-9121-5a0f-8d56-e8d7171a70a9', 'වෙන් වූ DNA දාම ස්ථාවර කිරීමයි.', 'වෙන් වූ DNA දාම ස්ථාවර කිරීමයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a19b44ae-97fc-4d27-b79b-0db6393c9489', '2a4a599c-9121-5a0f-8d56-e8d7171a70a9', 'අධික ව ඇඹරුණු DNA දාමවල ආතතිය සමනය කිරීමයි.', 'අධික ව ඇඹරුණු DNA දාමවල ආතතිය සමනය කිරීමයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('65819a04-65ab-4ba6-a04d-9f68662d29ee', '2a4a599c-9121-5a0f-8d56-e8d7171a70a9', 'DNA දාම අතර ඇති හයිඩ්‍රජන් බන්ධන කැඩීමයි.', 'DNA දාම අතර ඇති හයිඩ්‍රජන් බන්ධන කැඩීමයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4f942c72-0987-56aa-ba08-3cf7919d2911', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 33, '<p>සුන්‍යෂ්ටිකයන්ගේ පරිවර්තනය ප්‍රාග්න්‍යෂ්ටිකයන්ගේ පරිවර්තනයෙන් වෙනස් වන්නේ එය</p>', '<p>සුන්‍යෂ්ටිකයන්ගේ පරිවර්තනය ප්‍රාග්න්‍යෂ්ටිකයන්ගේ පරිවර්තනයෙන් වෙනස් වන්නේ එය</p>', NULL, 'සුන්‍යෂ්ටික සෛල වල ප්‍රතිලේඛනය (Transcription) න්‍යෂ්ටිය තුළත්, පරිවර්තනය (Translation) සෛල ප්ලාස්මයේත් සිදුවන බැවින් ප්‍රතිලේඛනය අවසන් වී mRNA න්‍යෂ්ටියෙන් පිටතට පැමිණෙන තෙක් පරිවර්තනය ආරම්භ විය නොහැක. නමුත් ප්‍රාග්න්‍යෂ්ටිකයන්ගේ න්‍යෂ්ටික ආවරණයක් නොමැති බැවින් ප්‍රතිලේඛනය සිදුවන අතරතුරදීම පරිවර්තනයද ආරම්භ වේ. එබැවින් පිළිතුර 1 වේ.', 'සුන්‍යෂ්ටික සෛල වල ප්‍රතිලේඛනය (Transcription) න්‍යෂ්ටිය තුළත්, පරිවර්තනය (Translation) සෛල ප්ලාස්මයේත් සිදුවන බැවින් ප්‍රතිලේඛනය අවසන් වී mRNA න්‍යෂ්ටියෙන් පිටතට පැමිණෙන තෙක් පරිවර්තනය ආරම්භ විය නොහැක. නමුත් ප්‍රාග්න්‍යෂ්ටිකයන්ගේ න්‍යෂ්ටික ආවරණයක් නොමැති බැවින් ප්‍රතිලේඛනය සිදුවන අතරතුරදීම පරිවර්තනයද ආරම්භ වේ. එබැවින් පිළිතුර 1 වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('db15db15-5212-4de0-86c6-680b7ab5f152', '4f942c72-0987-56aa-ba08-3cf7919d2911', 'ප්‍රතිලේඛනය අවසන් වීමට ප්‍රථම ආරම්භ නොවන බැවිනි.', 'ප්‍රතිලේඛනය අවසන් වීමට ප්‍රථම ආරම්භ නොවන බැවිනි.', NULL, 'sanitized', 'v1', 0, 1);
