INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d42095dc-f3e1-4e5e-ac44-0787a6b7d86e', '4f942c72-0987-56aa-ba08-3cf7919d2911', 'UAG, UAA හෝ UGA නැවතීමේ සංඥා ලෙස භාවිත කරන බැවිනි.', 'UAG, UAA හෝ UGA නැවතීමේ සංඥා ලෙස භාවිත කරන බැවිනි.', NULL, 'sanitized', 'v1', 2, 0);
