INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('79e20923-cae0-44b2-b662-ee10242d61c9', '57013c01-1c1d-56d5-81b2-a5c1a477d1a3', 'නිවර්තන වියළි වනාන්තර, චැපරාල්, ඇල්පයින් තුන්ද්‍රා', 'නිවර්තන වියළි වනාන්තර, චැපරාල්, ඇල්පයින් තුන්ද්‍රා', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('27046db0-6088-5a67-a6b7-c023bfd1d436', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 35, '<p>තර්ජනයට ලක් වූ ජීවීන් තිදෙනෙකු සහිත ප්‍රතිචාරය තෝරන්න.</p>', '<p>තර්ජනයට ලක් වූ ජීවීන් තිදෙනෙකු සහිත ප්‍රතිචාරය තෝරන්න.</p>', NULL, '2020-AL-Biology-Marking-Scheme-–-Sinhala-Medium.pdf ට අනුව නිවැරදි පිළිතුර 5 වේ. මහ මඩු (Cycas zeylanica), වෙසක් ඕකිඩ් (Dendrobium maccarthiae) සහ පුංචි ලේනා (Western purple-faced langur / Flame-striped jungle squirrel) යන සියල්ල ශ්‍රී ලංකාව තුළ තර්ජනයට ලක්වූ (threatened) විශේෂ ලෙස දැක්වේ. ඩෝඩෝ සහ ලෝම මැමත් නෂ්ට වූ විශේෂ වේ.', '2020-AL-Biology-Marking-Scheme-–-Sinhala-Medium.pdf ට අනුව නිවැරදි පිළිතුර 5 වේ. මහ මඩු (Cycas zeylanica), වෙසක් ඕකිඩ් (Dendrobium maccarthiae) සහ පුංචි ලේනා (Western purple-faced langur / Flame-striped jungle squirrel) යන සියල්ල ශ්‍රී ලංකාව තුළ තර්ජනයට ලක්වූ (threatened) විශේෂ ලෙස දැක්වේ. ඩෝඩෝ සහ ලෝම මැමත් නෂ්ට වූ විශේෂ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
