INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('65755cfe-f9af-5274-ba77-6f27f5d450c5', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 37, '<p>ක්ෂුද්‍රජීවීන් පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>ක්ෂුද්‍රජීවීන් පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'දිලීර සියල්ලම කාබනික ද්‍රව්‍ය මත යැපෙන රසායනික විෂමපෝෂීන් (Chemoheterotrophs) වන අතර, ඔවුන් මෘතෝපජීවී හෝ පරපෝෂී ලෙස පෝෂණය ලබාගනී. එබැවින් 2 වන ප්‍රකාශය නිවැරදිය. සයනොබැක්ටීරියාවල නයිට්‍රජන් තිර කරන්නේ විෂමකෝෂ්ඨ (heterocysts) තුළ මිස ඒකයිනීට තුළ නොවේ.', 'දිලීර සියල්ලම කාබනික ද්‍රව්‍ය මත යැපෙන රසායනික විෂමපෝෂීන් (Chemoheterotrophs) වන අතර, ඔවුන් මෘතෝපජීවී හෝ පරපෝෂී ලෙස පෝෂණය ලබාගනී. එබැවින් 2 වන ප්‍රකාශය නිවැරදිය. සයනොබැක්ටීරියාවල නයිට්‍රජන් තිර කරන්නේ විෂමකෝෂ්ඨ (heterocysts) තුළ මිස ඒකයිනීට තුළ නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e36af36a-8338-4401-9354-6189239f88a5', '65755cfe-f9af-5274-ba77-6f27f5d450c5', 'මයිකොප්ලාස්මාවන් සියල්ලෝම පාහේ සතුන්ගේ සහ ශාකවල පරපෝෂිතයෝ වෙති.', 'මයිකොප්ලාස්මාවන් සියල්ලෝම පාහේ සතුන්ගේ සහ ශාකවල පරපෝෂිතයෝ වෙති.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3aa1c7fa-1efc-4a09-8aa7-b2047e386e43', '65755cfe-f9af-5274-ba77-6f27f5d450c5', 'දිලීර යනු මෘතෝපජීවී හෝ පරපෝෂී හෝ පෝෂණ ක්‍රම දක්වන රසායනික විෂම පෝෂීන් ය.', 'දිලීර යනු මෘතෝපජීවී හෝ පරපෝෂී හෝ පෝෂණ ක්‍රම දක්වන රසායනික විෂම පෝෂීන් ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('51de45e3-63ac-485f-910e-62022e293f90', '65755cfe-f9af-5274-ba77-6f27f5d450c5', 'දම් සල්ෆර් නොවන බැක්ටීරියා ශක්ති ප්‍රභවය ලෙස ආලෝකය සහ කාබන් ප්‍රභවය ලෙස $CO_2$ භාවිත කරති.', 'දම් සල්ෆර් නොවන බැක්ටීරියා ශක්ති ප්‍රභවය ලෙස ආලෝකය සහ කාබන් ප්‍රභවය ලෙස $CO_2$ භාවිත කරති.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a2859767-4ea6-474e-b4bf-a6633d66b86d', '65755cfe-f9af-5274-ba77-6f27f5d450c5', 'ස්ට්‍රෙප්ටොකොකුස බැක්ටීරියා බහුතලිය ලෙස විභාජනය වේ.', 'ස්ට්‍රෙප්ටොකොකුස බැක්ටීරියා බහුතලිය ලෙස විභාජනය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b2ce5492-7661-4eff-bfb9-ae6373fbb96a', '65755cfe-f9af-5274-ba77-6f27f5d450c5', 'සයනොබැක්ටීරියාවල නයිට්‍රජන් තිර කිරීම උත්ප්‍රේරණය වන්නේ ඒකයිනීට තුළ අඩංගු නයිට්‍රජනේස් එන්සයිමය මගිනි.', 'සයනොබැක්ටීරියාවල නයිට්‍රජන් තිර කිරීම උත්ප්‍රේරණය වන්නේ ඒකයිනීට තුළ අඩංගු නයිට්‍රජනේස් එන්සයිමය මගිනි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b5ca1238-0f88-5e2e-92a5-9adae41e5db7', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 38, '<p>ඇතැම් බැක්ටීරිය ව්‍යාධි ජනකයන්</p>', '<p>ඇතැම් බැක්ටීරිය ව්‍යාධි ජනකයන්</p>', NULL, 'ඇතැම් බැක්ටීරියා සෛල පටල බිඳ හෙලීම සඳහා පොස්ෆොලයිපේස් (phospholipases) එන්සයිම නිපදවන අතර එය ඔවුන්ගේ ආක්‍රමණතාවට (invasiveness) සෘජුවම දායක වේ. අන්තඃධූලක යනු තාප ස්ථායී (heat-stable) ලිපොපොලිසැකරයිඩ වේ.', 'ඇතැම් බැක්ටීරියා සෛල පටල බිඳ හෙලීම සඳහා පොස්ෆොලයිපේස් (phospholipases) එන්සයිම නිපදවන අතර එය ඔවුන්ගේ ආක්‍රමණතාවට (invasiveness) සෘජුවම දායක වේ. අන්තඃධූලක යනු තාප ස්ථායී (heat-stable) ලිපොපොලිසැකරයිඩ වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fb8bdbc0-5881-49ce-9d6e-f129bf7029bc', 'b5ca1238-0f88-5e2e-92a5-9adae41e5db7', 'ආක්‍රමණතාවට දායක වන පොස්ෆොලයිපේස් නිපදවයි.', 'ආක්‍රමණතාවට දායක වන පොස්ෆොලයිපේස් නිපදවයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ee983f4c-7a41-42e9-9355-a4861fb2ac6c', 'b5ca1238-0f88-5e2e-92a5-9adae41e5db7', 'තාප අස්ථායි ලිපොපොලිසැකරයිඩ වන අන්තඃධූලක නිපදවයි.', 'තාප අස්ථායි ලිපොපොලිසැකරයිඩ වන අන්තඃධූලක නිපදවයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('45062d36-5902-45d9-8acd-df7afa7fc264', 'b5ca1238-0f88-5e2e-92a5-9adae41e5db7', 'ධාරක පටකයට ඇතුළු වීම සඳහා කෝෂ්ඨය සහ පිලයි භාවිත කරයි.', 'ධාරක පටකයට ඇතුළු වීම සඳහා කෝෂ්ඨය සහ පිලයි භාවිත කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1a837db7-3dd5-4b29-ab2f-26d2a8722964', 'b5ca1238-0f88-5e2e-92a5-9adae41e5db7', 'ධාරකයාගේ පරිවෘත්තියට වෙනසක් සිදු නොකර ධාරක සෛල වලින් පෝෂණ ද්‍රව්‍ය ලබා ගනී.', 'ධාරකයාගේ පරිවෘත්තියට වෙනසක් සිදු නොකර ධාරක සෛල වලින් පෝෂණ ද්‍රව්‍ය ලබා ගනී.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b892d465-49c2-4281-9dea-3f446fb0fb48', 'b5ca1238-0f88-5e2e-92a5-9adae41e5db7', 'සෛල සම්බන්ධ කරන බදාම ද්‍රව්‍යය බිඳ හෙලන ලෙසිතිනේස් නිපදවයි.', 'සෛල සම්බන්ධ කරන බදාම ද්‍රව්‍යය බිඳ හෙලන ලෙසිතිනේස් නිපදවයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('15565597-4d67-5dc3-9dd1-5b9d977dcdc2', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 39, '<p>ක්ෂුද්‍රජීවීන්ගේ කාර්යභාරයන් පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>ක්ෂුද්‍රජීවීන්ගේ කාර්යභාරයන් පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'නිවැරදි පිළිතුර 3 වේ. *Pseudomonas* වැනි බැක්ටීරියා පසේ නිර්වායු තත්ව යටතේ (ඔක්සිජන් සීමාකාරී විට) නයිට්‍රේට් ($NO_3^-$), නයිට්‍රජන් වායුව ($N_2$) බවට පත් කරමින් නයිට්‍රිහරණය (denitrification) සිදු කරයි. රයිසෝබියා යනු සහජීවී බැක්ටීරියා මිස නිදැලිවාසී නොවේ.', 'නිවැරදි පිළිතුර 3 වේ. *Pseudomonas* වැනි බැක්ටීරියා පසේ නිර්වායු තත්ව යටතේ (ඔක්සිජන් සීමාකාරී විට) නයිට්‍රේට් ($NO_3^-$), නයිට්‍රජන් වායුව ($N_2$) බවට පත් කරමින් නයිට්‍රිහරණය (denitrification) සිදු කරයි. රයිසෝබියා යනු සහජීවී බැක්ටීරියා මිස නිදැලිවාසී නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bc2ae938-671b-4e7d-9bfd-b84fe8b23bad', '15565597-4d67-5dc3-9dd1-5b9d977dcdc2', 'බැක්ටීරියා සහ දිලීර මගින් කාබනික ද්‍රව්‍ය ඛනිජභවනය කිරීමේදී ඔක්සිජන්, ජලය සහ $CO_2$ නිදහස් කෙරේ.', 'බැක්ටීරියා සහ දිලීර මගින් කාබනික ද්‍රව්‍ය ඛනිජභවනය කිරීමේදී ඔක්සිජන්, ජලය සහ $CO_2$ නිදහස් කෙරේ.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a7305af3-51e6-41ad-ab2c-045ecb041b0f', '15565597-4d67-5dc3-9dd1-5b9d977dcdc2', 'මෙතනොට්‍රෝෆ් ක්ෂුද්‍රජීවීහු සාගර අවසාදිත වලින් මීතේන් නිපදවති.', 'මෙතනොට්‍රෝෆ් ක්ෂුද්‍රජීවීහු සාගර අවසාදිත වලින් මීතේන් නිපදවති.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('30da095d-dab9-4e20-93a0-91aad37f210b', '15565597-4d67-5dc3-9dd1-5b9d977dcdc2', 'පසේ ඔක්සිජන් සීමාකාරී වන විට Pseudomonas sp. නයිට්‍රිහරණය සිදු කරයි.', 'පසේ ඔක්සිජන් සීමාකාරී වන විට Pseudomonas sp. නයිට්‍රිහරණය සිදු කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('04276ec2-90c0-4bfc-ad1d-6211d5593dc6', '15565597-4d67-5dc3-9dd1-5b9d977dcdc2', 'රයිසෝබියා යනු පසේ සිටින, නයිට්‍රජන් තිර කරන නිදැලිවාසී බැක්ටීරියාය.', 'රයිසෝබියා යනු පසේ සිටින, නයිට්‍රජන් තිර කරන නිදැලිවාසී බැක්ටීරියාය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3a6559b0-39d1-4370-9a0c-977c231b357b', '15565597-4d67-5dc3-9dd1-5b9d977dcdc2', 'මූලගෝල දිලීර සියල්ල ශාකවලට හිතකර ය.', 'මූලගෝල දිලීර සියල්ල ශාකවලට හිතකර ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fb80c281-77a3-5c76-a134-d7fb20882617', '89908dc2-901a-5c04-9a50-7c4c480b08cc', 40, '<p>රෝගය සහ ඊට හේතුකාරක වන ක්ෂුද්‍රජීවියා නිවැරදිව දක්වන ප්‍රතිචාරය තෝරන්න.</p>', '<p>රෝගය සහ ඊට හේතුකාරක වන ක්ෂුද්‍රජීවියා නිවැරදිව දක්වන ප්‍රතිචාරය තෝරන්න.</p>', NULL, 'මෙහිදී නිවැරදි ගැලපීම වන්නේ පිටගැස්ම (Tetanus) සඳහා *Clostridium tetani* බැක්ටීරියාව හේතු වීමයි. (සටහන: මුල් ප්‍රශ්න පත්‍රයේ ඇතැම් වචන පැහැදිලි නොවන බැවින් වඩාත් ගැලපෙන ලෙස විකල්ප සම්පූර්ණ කර ඇත. කොලරාව *Vibrio cholerae* නිසාත්, ටයිපොයිඩ්/උණසන්නිපාතය *Salmonella typhi* නිසාත්, බොටියුලිනියාව *Clostridium botulinum* නිසාත් ඇතිවේ. මාර්කින් ස්කීම් එකට අනුව පිළිතුර 2 වේ).', 'මෙහිදී නිවැරදි ගැලපීම වන්නේ පිටගැස්ම (Tetanus) සඳහා *Clostridium tetani* බැක්ටීරියාව හේතු වීමයි. (සටහන: මුල් ප්‍රශ්න පත්‍රයේ ඇතැම් වචන පැහැදිලි නොවන බැවින් වඩාත් ගැලපෙන ලෙස විකල්ප සම්පූර්ණ කර ඇත. කොලරාව *Vibrio cholerae* නිසාත්, ටයිපොයිඩ්/උණසන්නිපාතය *Salmonella typhi* නිසාත්, බොටියුලිනියාව *Clostridium botulinum* නිසාත් ඇතිවේ. මාර්කින් ස්කීම් එකට අනුව පිළිතුර 2 වේ).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
