INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('942fd0ed-d9ae-5639-848f-319002ecd1ac', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 1, '<p>What is the organ that mainly performs nitrogenous excretion of human?</p>', '<p>What is the organ that mainly performs nitrogenous excretion of human?</p>', NULL, 'The kidneys are the primary organs responsible for filtering nitrogenous wastes (such as urea) from the blood and excreting them in the form of urine.', 'The kidneys are the primary organs responsible for filtering nitrogenous wastes (such as urea) from the blood and excreting them in the form of urine.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
