INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('91dfdb29-f9f4-5d17-b483-3cd2abd61115', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 2, '<p>The unit of pressure, is,</p>', '<p>The unit of pressure, is,</p>', NULL, 'Pressure is defined as force per unit area ($P = F / A$). The unit of force is the Newton ($N$) and area is square meters ($m^2$), making the SI unit of pressure $N m^{-2}$, which is also called the Pascal ($Pa$).', 'Pressure is defined as force per unit area ($P = F / A$). The unit of force is the Newton ($N$) and area is square meters ($m^2$), making the SI unit of pressure $N m^{-2}$, which is also called the Pascal ($Pa$).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
