INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9ef6cf25-eeb6-5475-9ec3-ff7c1256a897', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 12, '<p>Which of the following is a change that occurs after the process of fertilization of a flower?</p>', '<p>Which of the following is a change that occurs after the process of fertilization of a flower?</p>', NULL, 'After fertilization in a flowering plant, the ovules develop into seeds, while the surrounding ovary matures into the fruit. The ovary wall forms the pericarp, and the integuments of the ovule become the seed coat.', 'After fertilization in a flowering plant, the ovules develop into seeds, while the surrounding ovary matures into the fruit. The ovary wall forms the pericarp, and the integuments of the ovule become the seed coat.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
