INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('02bff48c-0d5e-50fa-be6d-3842aaf6b1eb', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 13, '<p>Which of the following is not a characteristic of the smooth muscle tissue?</p>', '<p>Which of the following is not a characteristic of the smooth muscle tissue?</p>', NULL, 'Smooth muscle tissue is named ''smooth'' precisely because it lacks the cross-striations seen in skeletal and cardiac muscle tissues.', 'Smooth muscle tissue is named ''smooth'' precisely because it lacks the cross-striations seen in skeletal and cardiac muscle tissues.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
