INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('649f04f5-de5d-5dd0-80cd-ba912d6969f7', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 14, '<p>Consider the following statements given about mechanical waves.<br>A - The frequency of the wave changes on entering from one medium into another.<br>B - The speed of the wave does not depend on its frequency.<br>C - The speed of the wave depends on the medium through which it travels.<br><br>Of the above, true statement/s is/are,</p>', '<p>Consider the following statements given about mechanical waves.<br>A - The frequency of the wave changes on entering from one medium into another.<br>B - The speed of the wave does not depend on its frequency.<br>C - The speed of the wave depends on the medium through which it travels.<br><br>Of the above, true statement/s is/are,</p>', NULL, 'When a wave travels from one medium to another, its frequency remains constant as it solely depends on the source. Wave speed depends on the physical properties of the medium. For non-dispersive media, wave speed is independent of frequency.', 'When a wave travels from one medium to another, its frequency remains constant as it solely depends on the source. Wave speed depends on the physical properties of the medium. For non-dispersive media, wave speed is independent of frequency.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
