INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c7404a4a-894c-5c1f-8ca4-ca2fed4db136', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 15, '<p>Given below are some information regarding a certain element.<br>• It comes second in the order of abundance of elements in the Earth''s crust.<br>• Shows semi-conductor properties.<br>• Shows metallic properties as well as non-metallic properties.<br><br>This element is,</p>', '<p>Given below are some information regarding a certain element.<br>• It comes second in the order of abundance of elements in the Earth''s crust.<br>• Shows semi-conductor properties.<br>• Shows metallic properties as well as non-metallic properties.<br><br>This element is,</p>', NULL, 'Silicon ($Si$) is a metalloid, meaning it exhibits properties of both metals and non-metals. It is widely used as a semiconductor and is the second most abundant element in the Earth''s crust (after Oxygen).', 'Silicon ($Si$) is a metalloid, meaning it exhibits properties of both metals and non-metals. It is widely used as a semiconductor and is the second most abundant element in the Earth''s crust (after Oxygen).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
