INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('77d962cd-1abf-55b8-868e-43a9e02f5b4b', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 17, '<p>Of the following compounds, what is the compound in which the percentage of oxygen by mass is 50%?<br>($H=1$, $C=12$, $N=14$, $O=16$, $Mg=24$, $Ca=40$)</p>', '<p>Of the following compounds, what is the compound in which the percentage of oxygen by mass is 50%?<br>($H=1$, $C=12$, $N=14$, $O=16$, $Mg=24$, $Ca=40$)</p>', NULL, 'For $CH_3OH$, the molar mass is $12 + (1 \times 3) + 16 + 1 = 32\text{ g mol}^{-1}$. The mass of the single Oxygen atom is $16$. Therefore, the percentage by mass of Oxygen is $(16 / 32) \times 100\% = 50\%$.', 'For $CH_3OH$, the molar mass is $12 + (1 \times 3) + 16 + 1 = 32\text{ g mol}^{-1}$. The mass of the single Oxygen atom is $16$. Therefore, the percentage by mass of Oxygen is $(16 / 32) \times 100\% = 50\%$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
