INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('13e9cbdb-4606-5061-82a2-df10e81abad8', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 18, '<p>What is the advantage of using the handle fixed to a door in the occasions of opening and closing it?</p>', '<p>What is the advantage of using the handle fixed to a door in the occasions of opening and closing it?</p>', NULL, 'The turning effect (moment) of a force is calculated as $\text{Force} \times \text{Perpendicular Distance}$ from the pivot. Placing a handle far from the hinge maximizes this distance, meaning a smaller force is required to achieve the necessary turning effect to open or close the door.', 'The turning effect (moment) of a force is calculated as $\text{Force} \times \text{Perpendicular Distance}$ from the pivot. Placing a handle far from the hinge maximizes this distance, meaning a smaller force is required to achieve the necessary turning effect to open or close the door.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
