INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('aaf5a37b-1957-5363-a997-5d0db4365289', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 20, '<p>What is the statement that is true with respect to all the molecules given below?<br>$CO_2$, $NH_3$, $H_2O$</p>', '<p>What is the statement that is true with respect to all the molecules given below?<br>$CO_2$, $NH_3$, $H_2O$</p>', NULL, 'In $CO_2$ (C is central), $NH_3$ (N is central), and $H_2O$ (O is central), the central atoms share electrons with surrounding atoms to successfully achieve a stable valence shell of eight electrons (a complete octet).', 'In $CO_2$ (C is central), $NH_3$ (N is central), and $H_2O$ (O is central), the central atoms share electrons with surrounding atoms to successfully achieve a stable valence shell of eight electrons (a complete octet).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b8502315-29c3-4823-ba2c-21262458b37c', 'aaf5a37b-1957-5363-a997-5d0db4365289', 'The electron octet of the central atom of the molecules is complete.', 'The electron octet of the central atom of the molecules is complete.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('dbb2125e-5a8c-492b-a070-5ecb542752f3', 'aaf5a37b-1957-5363-a997-5d0db4365289', 'Only single bonds occur among the atoms of the molecules.', 'Only single bonds occur among the atoms of the molecules.', NULL, 'sanitized', 'v1', 1, 0);
