INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('aa7eb94e-9662-502c-896f-1dab8c031de8', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 21, '<p>Consider the following statements given about heat transfer.<br>A - Sea breeze and land breeze occur due to conduction.<br>B - Heat reaches the Earth from the Sun by radiation.<br>C - When a metal spoon is put into a hot cup of tea it is heated by convection.<br><br>Of the above, true statement/s is/are,</p>', '<p>Consider the following statements given about heat transfer.<br>A - Sea breeze and land breeze occur due to conduction.<br>B - Heat reaches the Earth from the Sun by radiation.<br>C - When a metal spoon is put into a hot cup of tea it is heated by convection.<br><br>Of the above, true statement/s is/are,</p>', NULL, 'Statement A is false because sea/land breezes are caused by convection currents in the air. Statement C is false because a solid metal spoon is heated by conduction. Statement B is true; thermal radiation can travel through the vacuum of space to reach Earth.', 'Statement A is false because sea/land breezes are caused by convection currents in the air. Statement C is false because a solid metal spoon is heated by conduction. Statement B is true; thermal radiation can travel through the vacuum of space to reach Earth.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
