INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d3e8098f-818f-5818-9d83-535d5a26d8d2', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 22, '<p>A function of the hormone adrenaline is,</p>', '<p>A function of the hormone adrenaline is,</p>', NULL, 'Adrenaline (also known as epinephrine) is often referred to as the ''fight or flight'' hormone. It prepares the body for sudden stress or emergency action by increasing heart rate, dilating pupils, and elevating blood sugar levels.', 'Adrenaline (also known as epinephrine) is often referred to as the ''fight or flight'' hormone. It prepares the body for sudden stress or emergency action by increasing heart rate, dilating pupils, and elevating blood sugar levels.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
