INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0d09d9ec-565a-569a-80d9-92f767913d40', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 23, '<p>What is the amount of moles of $O_2$ in $64\text{ g}$ of oxygen? ($O=16$)</p>', '<p>What is the amount of moles of $O_2$ in $64\text{ g}$ of oxygen? ($O=16$)</p>', NULL, 'The molar mass of an $O_2$ molecule is $16 \times 2 = 32\text{ g mol}^{-1}$. The number of moles is calculated by dividing mass by molar mass: $64\text{ g} / 32\text{ g mol}^{-1} = 2\text{ moles}$.', 'The molar mass of an $O_2$ molecule is $16 \times 2 = 32\text{ g mol}^{-1}$. The number of moles is calculated by dividing mass by molar mass: $64\text{ g} / 32\text{ g mol}^{-1} = 2\text{ moles}$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
