INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('89789ed8-674d-5a4e-959c-22b0fcbfa404', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 24, '<p>In a transformer, the voltage supplied to the primary coil is $120\text{ V}$ while the voltage received from the secondary coil is $12\text{ V}$. If the current flowing through the primary coil is $2\text{ A}$, what is the current flowing through the secondary coil?</p>', '<p>In a transformer, the voltage supplied to the primary coil is $120\text{ V}$ while the voltage received from the secondary coil is $12\text{ V}$. If the current flowing through the primary coil is $2\text{ A}$, what is the current flowing through the secondary coil?</p>', NULL, 'Assuming an ideal transformer, the input power equals the output power ($V_p I_p = V_s I_s$). Therefore, $120\text{ V} \times 2\text{ A} = 12\text{ V} \times I_s$. Solving for $I_s$ gives $240 / 12 = 20\text{ A}$.', 'Assuming an ideal transformer, the input power equals the output power ($V_p I_p = V_s I_s$). Therefore, $120\text{ V} \times 2\text{ A} = 12\text{ V} \times I_s$. Solving for $I_s$ gives $240 / 12 = 20\text{ A}$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
