INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6ad127bd-5031-5a58-8b1e-ca7cfe151ba1', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 25, '<p>Consider the following statements given with regard to anaerobic respiration.<br>A - Lactic acid is produced during the anaerobic respiration taking place in animal cells.<br>B - The amount of energy produced in anaerobic respiration is higher than that in aerobic respiration.<br>C - A part of energy produced during anaerobic respiration is stored as ATP.<br><br>Of the above, the true statements are,</p>', '<p>Consider the following statements given with regard to anaerobic respiration.<br>A - Lactic acid is produced during the anaerobic respiration taking place in animal cells.<br>B - The amount of energy produced in anaerobic respiration is higher than that in aerobic respiration.<br>C - A part of energy produced during anaerobic respiration is stored as ATP.<br><br>Of the above, the true statements are,</p>', NULL, 'Statement B is false because aerobic respiration produces significantly more ATP (energy) than anaerobic respiration. Statements A and C are factual descriptions of anaerobic pathways in animal cells.', 'Statement B is false because aerobic respiration produces significantly more ATP (energy) than anaerobic respiration. Statements A and C are factual descriptions of anaerobic pathways in animal cells.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
