INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c253ca7f-b964-5969-bef5-a32c01426f57', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 27, '<p>Consider the following statements.<br>A - In chemical industries, catalysts are used to obtain a higher yield in a shorter period of time.<br>B - Catalysts increase as well as decrease the rate of chemical reactions.<br><br>Of the above statements,</p>', '<p>Consider the following statements.<br>A - In chemical industries, catalysts are used to obtain a higher yield in a shorter period of time.<br>B - Catalysts increase as well as decrease the rate of chemical reactions.<br><br>Of the above statements,</p>', NULL, 'In standard secondary science curricula, catalysts are specifically defined as substances that increase the rate of a reaction without being consumed. Substances that decrease the rate are distinctly categorized as inhibitors. Therefore, statement B is considered false.', 'In standard secondary science curricula, catalysts are specifically defined as substances that increase the rate of a reaction without being consumed. Substances that decrease the rate are distinctly categorized as inhibitors. Therefore, statement B is considered false.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, s