INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c88f1ee2-ce33-5201-8d1b-250f8a036e7c', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 28, '<p>Which of the following phenomena agrees most with Newton''s third law of motion?</p>', '<p>Which of the following phenomena agrees most with Newton''s third law of motion?</p>', NULL, 'Newton''s third law states that for every action, there is an equal and opposite reaction. When the falling ball hits the ground (action force), the ground exerts an equal upward force on the ball (reaction force), causing it to bounce.', 'Newton''s third law states that for every action, there is an equal and opposite reaction. When the falling ball hits the ground (action force), the ground exerts an equal upward force on the ball (reaction force), causing it to bounce.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
