INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fcfcca81-106c-52b6-8829-e117b3315dc5', '8ae986d5-15c1-5440-a8bb-798ba5c1afd9', 31, '<p>What is the mass of $C_6H_{12}O_6$ required to prepare $1\text{ dm}^3$ of a $0.1\text{ mol dm}^{-3}$ glucose solution?<br>($H=1$, $C=12$, $O=16$)</p>', '<p>What is the mass of $C_6H_{12}O_6$ required to prepare $1\text{ dm}^3$ of a $0.1\text{ mol dm}^{-3}$ glucose solution?<br>($H=1$, $C=12$, $O=16$)</p>', NULL, 'The molar mass of glucose ($C_6H_{12}O_6$) is $(12 \times 6) + (1 \times 12) + (16 \times 6) = 180\text{ g mol}^{-1}$. A $1\text{ dm}^3$ solution at $0.1\text{ mol dm}^{-3}$ requires $0.1\text{ moles}$ of solute. Mass $= 0.1\text{ mol} \times 180\text{ g mol}^{-1} = 18\text{ g}$.', 'The molar mass of glucose ($C_6H_{12}O_6$) is $(12 \times 6) + (1 \times 12) + (16 \times 6) = 180\text{ g mol}^{-1}$. A $1\text{ dm}^3$ solution at $0.1\text{ mol dm}^{-3}$ requires $0.1\text{ moles}$ of solute. Mass $= 0.1\text{ mol} \times 180\text{ g mol}^{-1} = 18\text{ g}$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
