INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('33c9c32f-7868-54c9-9fb6-3aa012a3c88a', '94ade899-3dad-5391-8f11-30c80ef9b720', 4, '<p>$2x(x + 4)$ සුළු කරන්න.</p>', '<p>$2x(x + 4)$ සුළු කරන්න.</p>', NULL, '<p>වරහන් ඉවත් කළ විට $2x \cdot x + 2x \cdot 4 = 2x^2 + 8x$.</p>', '<p>වරහන් ඉවත් කළ විට $2x \cdot x + 2x \cdot 4 = 2x^2 + 8x$.</p>', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
