INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8d562b3c-f058-51da-bd7e-b62f1bd1768b', '94ade899-3dad-5391-8f11-30c80ef9b720', 5, '<p>$2x + 1 = 5$ නම් $x$ හි අගය සොයන්න.</p>', '<p>$2x + 1 = 5$ නම් $x$ හි අගය සොයන්න.</p>', NULL, '<p>$2x = 5 - 1 = 4$. එබැවින් $x = \frac{4}{2} = 2$.</p>', '<p>$2x = 5 - 1 = 4$. එබැවින් $x = \frac{4}{2} = 2$.</p>', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
