INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d1a6d68e-4f2f-5342-b69e-57ee6379dd16', '9548b718-47d5-5969-a03d-ceaebef2631d', 9, '<p>මලය රට හෙවත් මධ්‍ය කඳුකරය රජරට අවධියේදී වඩාත් ප්‍රසිද්ධියට පත් වීමට මුල් වූ හේතුව කුමක්ද?</p>', '<p>මලය රට හෙවත් මධ්‍ය කඳුකරය රජරට අවධියේදී වඩාත් ප්‍රසිද්ධියට පත් වීමට මුල් වූ හේතුව කුමක්ද?</p>', NULL, 'රජරට රාජධානි සමයේදී දේශීය අරගල හෝ විදේශ ආක්‍රමණ සිදු වූ විට රජවරුන් සහ පාලකයන් සිය ආරක්ෂාව පතා පසුබැස ගියේ මලය රට හෙවත් මධ්‍ය කඳුකරයටයි. එහි ඇති දුර්ග මාර්ග සහ ස්වාභාවික ආරක්ෂාව ඊට හේතු විය.', 'රජරට රාජධානි සමයේදී දේශීය අරගල හෝ විදේශ ආක්‍රමණ සිදු වූ විට රජවරුන් සහ පාලකයන් සිය ආරක්ෂාව පතා පසුබැස ගියේ මලය රට හෙවත් මධ්‍ය කඳුකරයටයි. එහි ඇති දුර්ග මාර්ග සහ ස්වාභාවික ආරක්ෂාව ඊට හේතු විය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('873dec3a-5b4c-4961-971d-1376503e3d56', 'd1a6d68e-4f2f-5342-b69e-57ee6379dd16', 'සුවදායක දේශගුණයක් පැවතීම', 'සුවදායක දේශගුණයක් පැවතීම', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c8ad2b95-5cd1-4b72-8e25-dedcfade7a9f', 'd1a6d68e-4f2f-5342-b69e-57ee6379dd16', 'ප්‍රධාන ගංගාවල පෝෂක ප්‍රදේශය වීම', 'ප්‍රධාන ගංගාවල පෝෂක ප්‍රදේශය වීම', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ae30490c-a226-4c93-b184-62ac16031701', 'd1a6d68e-4f2f-5342-b69e-57ee6379dd16', 'ආක්‍රමණ හා අභ්‍යන්තර අරගල අවස්ථාවලදී පාලකයින්ට ආරක්ෂක ස්ථානයක් වීම', 'ආක්‍රමණ හා අභ්‍යන්තර අරගල අවස්ථාවලදී පාලකයින්ට ආරක්ෂක ස්ථානයක් වීම', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('814a8a8b-1d2a-443b-9a37-b746982a0218', 'd1a6d68e-4f2f-5342-b69e-57ee6379dd16', 'විදේශ වෙළෙඳාම සඳහා වෙළෙඳ ද්‍රව්‍ය සැපයූ ප්‍රදේශයක් වීම', 'විදේශ වෙළෙඳාම සඳහා වෙළෙඳ ද්‍රව්‍ය සැපයූ ප්‍රදේශයක් වීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('0886c70d-d0a0-5063-83de-636f9f4afde4', '9548b718-47d5-5969-a03d-ceaebef2631d', 10, '<p>ප්‍රථමවරට දිවයිනේ ග්‍රාම සීමා නියම කරවන ලද රජතුමා කවුරුන්ද?</p>', '<p>ප්‍රථමවරට දිවයිනේ ග්‍රාම සීමා නියම කරවන ලද රජතුමා කවුරුන්ද?</p>', NULL, 'මහාවංසයට අනුව ශ්‍රී ලංකාවේ ප්‍රථම වතාවට ග්‍රාම සීමා (ගම් මායිම්) නියම කරමින් පරිපාලන කටයුතු ක්‍රමවත් කරන ලද්දේ පණ්ඩුකාභය රජතුමා විසිනි.', 'මහාවංසයට අනුව ශ්‍රී ලංකාවේ ප්‍රථම වතාවට ග්‍රාම සීමා (ගම් මායිම්) නියම කරමින් පරිපාලන කටයුතු ක්‍රමවත් කරන ලද්දේ පණ්ඩුකාභය රජතුමා විසිනි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
