INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('928ced63-7cde-546c-81b2-381be615ddf9', '9548b718-47d5-5969-a03d-ceaebef2631d', 14, '<p>ගෘහ දණ්ඩ බද්ද යනු,</p>', '<p>ගෘහ දණ්ඩ බද්ද යනු,</p>', NULL, 'පුරාණ ලංකාවේ අපරාධකරුවෙකු ගමක සැඟවී සිටින විට, ඔහුව අල්ලා රජයට භාරදෙන තුරු මුළු ගමටම පනවන ලද දඩයක් හෝ බද්දක් ''දසගම් දණ්ඩ'' හෙවත් ගෘහ දණ්ඩ බද්ද ලෙස හැඳින්විණි.', 'පුරාණ ලංකාවේ අපරාධකරුවෙකු ගමක සැඟවී සිටින විට, ඔහුව අල්ලා රජයට භාරදෙන තුරු මුළු ගමටම පනවන ලද දඩයක් හෝ බද්දක් ''දසගම් දණ්ඩ'' හෙවත් ගෘහ දණ්ඩ බද්ද ලෙස හැඳින්විණි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('40615a77-24d0-4b16-b431-b6073a842090', '928ced63-7cde-546c-81b2-381be615ddf9', 'වැව් වල ජලය භාවිත කරන්නන්ගෙන් අය කළ බද්දකි.', 'වැව් වල ජලය භාවිත කරන්නන්ගෙන් අය කළ බද්දකි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('52537730-6042-4b0a-9c50-9fce2a9fda43', '928ced63-7cde-546c-81b2-381be615ddf9', 'රජුට අයත් ඉඩම් වගා කිරීම වෙනුවෙන් ගොවීන් විසින් රජයට ගෙවන ලද්දකි.', 'රජුට අයත් ඉඩම් වගා කිරීම වෙනුවෙන් ගොවීන් විසින් රජයට ගෙවන ලද්දකි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c8c45922-8d19-4877-b850-429933a52775', '928ced63-7cde-546c-81b2-381be615ddf9', 'ඇළ මාර්ගවල මසුන් ඇල්ලීම වෙනුවෙන් රජයට ගෙවිය යුතු බද්දකි.', 'ඇළ මාර්ගවල මසුන් ඇල්ලීම වෙනුවෙන් රජයට ගෙවිය යුතු බද්දකි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c7b77b21-5119-46da-b643-2e46e5ebcf19', '928ced63-7cde-546c-81b2-381be615ddf9', 'සැඟවී සිටි අපරාධකරුවන් අල්ලා ගන්නා තෙක් ඔවුන් ජීවත් වූ ගම්වල වැසියන්ගෙන් අය කරන ලද්දකි.', 'සැඟවී සිටි අපරාධකරුවන් අල්ලා ගන්නා තෙක් ඔවුන් ජීවත් වූ ගම්වල වැසියන්ගෙන් අය කරන ලද්දකි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ddb5c53e-77e9-53f5-871e-1c86d2c5d51e', '9548b718-47d5-5969-a03d-ceaebef2631d', 15, '<p>ශ්‍රී ලාංකික රජවරු කිහිපදෙනෙකුගේ නම් I තීරුවේ ද, ඔවුන්ගේ රාජධානි II තීරුවේ ද දැක්වේ. I තීරුවේ අනුපිළිවෙළට II තීරුව ගැළපූ විට නිවැරදි පිළිතුර කුමක්ද?<br><br><b>I තීරුව</b><br>1. පළමුවන විජයබාහු<br>2. දෙවන පරාක්‍රමබාහු<br>3. දුටුගැමුණු<br><br><b>II තීරුව</b><br>A - අනුරාධපුරය<br>B - පොළොන්නරුව<br>C - දඹදෙණිය<br>D - මහනුවර</p>', '<p>ශ්‍රී ලාංකික රජවරු කිහිපදෙනෙකුගේ නම් I තීරුවේ ද, ඔවුන්ගේ රාජධානි II තීරුවේ ද දැක්වේ. I තීරුවේ අනුපිළිවෙළට II තීරුව ගැළපූ විට නිවැරදි පිළිතුර කුමක්ද?<br><br><b>I තීරුව</b><br>1. පළමුවන විජයබාහු<br>2. දෙවන පරාක්‍රමබාහු<br>3. දුටුගැමුණු<br><br><b>II තීරුව</b><br>A - අනුරාධපුරය<br>B - පොළොන්නරුව<br>C - දඹදෙණිය<br>D - මහනුවර</p>', NULL, 'පළමුවන විජයබාහු රජුගේ රාජධානිය පොළොන්නරුවයි (B). දෙවන පරාක්‍රමබාහු රජු දඹදෙණිය කේන්ද්‍ර කරගෙන පාලනය කළේය (C). දුටුගැමුණු රජු අනුරාධපුරය පාලනය කළේය (A). ඒ අනුව නිවැරදි අනුපිළිවෙළ BCA වේ.', 'පළමුවන විජයබාහු රජුගේ රාජධානිය පොළොන්නරුවයි (B). දෙවන පරාක්‍රමබාහු රජු දඹදෙණිය කේන්ද්‍ර කරගෙන පාලනය කළේය (C). දුටුගැමුණු රජු අනුරාධපුරය පාලනය කළේය (A). ඒ අනුව නිවැරදි අනුපිළිවෙළ BCA වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
