INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3dd9081e-518a-4082-a308-3bc07463d808', '58a33e78-7948-5978-9140-cdf2b55f9fac', 'නටබුන්ව තිබූ වෙහෙර විහාර පිළිසකර කිරීම', 'නටබුන්ව තිබූ වෙහෙර විහාර පිළිසකර කිරීම', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('30cfa0f0-0d95-5503-b499-c64e8668fd05', '9548b718-47d5-5969-a03d-ceaebef2631d', 17, '<p>ක්‍රිස්තු වර්ෂ 15 වන සියවස මැදදී ක්‍රිස්තියානි සහ මුස්ලිම් භක්තිකයන් සටන් කළේ කුමන නගරයේ අයිතිය ලබා ගැනීම උදෙසාද?</p>', '<p>ක්‍රිස්තු වර්ෂ 15 වන සියවස මැදදී ක්‍රිස්තියානි සහ මුස්ලිම් භක්තිකයන් සටන් කළේ කුමන නගරයේ අයිතිය ලබා ගැනීම උදෙසාද?</p>', NULL, 'ක්‍රි.ව. 1453 දී තුර්කි මුස්ලිම්වරුන් විසින් ක්‍රිස්තියානින් සතුව තිබූ කොන්ස්තන්තිනෝපල් නගරය යටත් කරගැනීම යුරෝපා ඉතිහාසයේ හැරවුම් ලක්ෂ්‍යයකි. මෙය පෙරදිග-අපරදිග වෙළඳ මාර්ගය අවහිර වීමට හේතු විය.', 'ක්‍රි.ව. 1453 දී තුර්කි මුස්ලිම්වරුන් විසින් ක්‍රිස්තියානින් සතුව තිබූ කොන්ස්තන්තිනෝපල් නගරය යටත් කරගැනීම යුරෝපා ඉතිහාසයේ හැරවුම් ලක්ෂ්‍යයකි. මෙය පෙරදිග-අපරදිග වෙළඳ මාර්ගය අවහිර වීමට හේතු විය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
