INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('f12e6832-56c5-589b-a957-502b97a71693', '9548b718-47d5-5969-a03d-ceaebef2631d', 21, '<p>කෘෂිකර්මාන්තයේදී පේළියට වැපිරීමේ ක්‍රමය මගින් අත්වන වාසියක් වන්නේ,</p>', '<p>කෘෂිකර්මාන්තයේදී පේළියට වැපිරීමේ ක්‍රමය මගින් අත්වන වාසියක් වන්නේ,</p>', NULL, 'අතින් විසුරුවා හැරීමේ ක්‍රමයට වඩා පේළියට බීජ වැපිරීමේදී බීජ අපතේ යාම අවම වේ. මේ නිසා වගාවට අවශ්‍ය බීජ ප්‍රමාණය අඩු කරගත හැකිය.', 'අතින් විසුරුවා හැරීමේ ක්‍රමයට වඩා පේළියට බීජ වැපිරීමේදී බීජ අපතේ යාම අවම වේ. මේ නිසා වගාවට අවශ්‍ය බීජ ප්‍රමාණය අඩු කරගත හැකිය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2b856e23-212d-4816-95a6-c9ba0bed73a7', 'f12e6832-56c5-589b-a957-502b97a71693', 'වගා භූමිවල හටගන්නා වල් පැලෑටි ප්‍රමාණය අඩු වීම ය.', 'වගා භූමිවල හටගන්නා වල් පැලෑටි ප්‍රමාණය අඩු වීම ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9e94647b-9def-4a38-94de-49fd0ce42864', 'f12e6832-56c5-589b-a957-502b97a71693', 'වගාවන්ට පොහොර යෙදීම පහසු වීම ය.', 'වගාවන්ට පොහොර යෙදීම පහසු වීම ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7f5436f4-693c-41f3-8660-5ed2b11ef045', 'f12e6832-56c5-589b-a957-502b97a71693', 'වගාවට වැළඳෙන ලෙඩ රෝග ව්‍යාප්තිය අවම වීම ය.', 'වගාවට වැළඳෙන ලෙඩ රෝග ව්‍යාප්තිය අවම වීම ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('42b1c57d-e3b1-49a4-8574-323b9220d056', 'f12e6832-56c5-589b-a957-502b97a71693', 'වැපිරීමට අවශ්‍ය බීජ ප්‍රමාණය අඩු කරගැනීමට හැකි වීමය.', 'වැපිරීමට අවශ්‍ය බීජ ප්‍රමාණය අඩු කරගැනීමට හැකි වීමය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('dad93dfb-365d-5405-9249-620677064719', '9548b718-47d5-5969-a03d-ceaebef2631d', 22, '<p>වර්ෂ 1818 නිදහස් සටන අසාර්ථක වීමට හේතු වූයේ,</p>', '<p>වර්ෂ 1818 නිදහස් සටන අසාර්ථක වීමට හේතු වූයේ,</p>', NULL, '1818 ඌව-වෙල්ලස්ස කැරැල්ලේදී රජු ලෙස පෙනී සිටි ''දොරේසාමි'' කුමරුට සැබෑ රාජ්‍ය උරුමයක් නොමැති බව (ඔහු හිටපු භික්ෂුවක් බව) හෙළිවීමත් සමග කැරැල්ලට ලැබුණු ජනතා සහාය සහ නායකයින්ගේ විශ්වාසය බිඳ වැටුණි. මෙය සටන අසාර්ථක වීමට ප්‍රබල හේතුවක් විය.', '1818 ඌව-වෙල්ලස්ස කැරැල්ලේදී රජු ලෙස පෙනී සිටි ''දොරේසාමි'' කුමරුට සැබෑ රාජ්‍ය උරුමයක් නොමැති බව (ඔහු හිටපු භික්ෂුවක් බව) හෙළිවීමත් සමග කැරැල්ලට ලැබුණු ජනතා සහාය සහ නායකයින්ගේ විශ්වාසය බිඳ වැටුණි. මෙය සටන අසාර්ථක වීමට ප්‍රබල හේතුවක් විය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('25dcd928-6a2d-478f-84dd-1349e00f1eea', 'dad93dfb-365d-5405-9249-620677064719', 'සත්කෝරළය හරහා උඩරටට හමුදා සහ අවි ආයුධ යැවීමට ඉංග්‍රීසින්ට හැකි වීමය.', 'සත්කෝරළය හරහා උඩරටට හමුදා සහ අවි ආයුධ යැවීමට ඉංග්‍රීසින්ට හැකි වීමය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('03df3d0e-bbb9-4f08-8bb5-f10947d904de', 'dad93dfb-365d-5405-9249-620677064719', 'සාමාන්‍ය ජනතාවගේ සහයෝගය නොලැබීම ය.', 'සාමාන්‍ය ජනතාවගේ සහයෝගය නොලැබීම ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5fc30eb2-304d-48a1-8913-e878a85894d5', 'dad93dfb-365d-5405-9249-620677064719', 'ගම්සභා ක්‍රමය අහෝසි කිරීම නිසා ජනතාව එක්රැස් කිරීම දුෂ්කර වීම ය.', 'ගම්සභා ක්‍රමය අහෝසි කිරීම නිසා ජනතාව එක්රැස් කිරීම දුෂ්කර වීම ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('88bd9bd4-8c88-4f41-b69a-c8a665e6ff4a', 'dad93dfb-365d-5405-9249-620677064719', 'රජු ලෙස ඉදිරිපත් වූ තැනැත්තාට රාජ්‍ය උරුමයක් නොමැති බව හෙළි වීම ය.', 'රජු ලෙස ඉදිරිපත් වූ තැනැත්තාට රාජ්‍ය උරුමයක් නොමැති බව හෙළි වීම ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('05b97395-0867-56ae-9770-e68db4ec37c4', '9548b718-47d5-5969-a03d-ceaebef2631d', 23, '<p>පහත වගුවේ I තීරුවෙන් බ්‍රිතාන්‍යයන් ශ්‍රී ලංකාවේ බලය පිහිටුවා ගැනීමේදී වැදගත් වූ වර්ෂ ද II තීරුවෙන් එම වර්ෂ වල වූ සිදුවීම් ද දැක්වේ. I තීරුවට අනුව II තීරුව ගැළපූ විට නිවැරදි පිළිතුර කුමක්ද?<br><br><b>I තීරුව</b><br>1. 1796<br>2. 1802<br>3. 1815<br><br><b>II තීරුව</b><br>A - මුහුදුබඩ ප්‍රදේශ බ්‍රිතාන්‍ය කිරීටය යටතට ගැනීම<br>B - පෙරදිග ඉන්දියා වෙළෙඳ සමාගමේ පාලනය ආරම්භ වීම<br>C - ද්විත්ව පාලනය ආරම්භ වීම<br>D - උඩරට රාජධානිය ඉංග්‍රීසීන් යටතට ගැනීම</p>', '<p>පහත වගුවේ I තීරුවෙන් බ්‍රිතාන්‍යයන් ශ්‍රී ලංකාවේ බලය පිහිටුවා ගැනීමේදී වැදගත් වූ වර්ෂ ද II තීරුවෙන් එම වර්ෂ වල වූ සිදුවීම් ද දැක්වේ. I තීරුවට අනුව II තීරුව ගැළපූ විට නිවැරදි පිළිතුර කුමක්ද?<br><br><b>I තීරුව</b><br>1. 1796<br>2. 1802<br>3. 1815<br><br><b>II තීරුව</b><br>A - මුහුදුබඩ ප්‍රදේශ බ්‍රිතාන්‍ය කිරීටය යටතට ගැනීම<br>B - පෙරදිග ඉන්දියා වෙළෙඳ සමාගමේ පාලනය ආරම්භ වීම<br>C - ද්විත්ව පාලනය ආරම්භ වීම<br>D - උඩරට රාජධානිය ඉංග්‍රීසීන් යටතට ගැනීම</p>', NULL, '1796 දී ඉංග්‍රීසීන් මුහුදුබඩ ප්‍රදේශ යටත් කරගත් අතර මුලින්ම පෙරදිග ඉන්දියා වෙළෙඳ සමාගම මගින් පාලනය ගෙන ගියේය (1 -> B). 1802 දී එම ප්‍රදේශ කෙළින්ම බ්‍රිතාන්‍ය කිරීටය යටතට පත් විය (2 -> A). 1815 දී උඩරට ගිවිසුම මගින් උඩරට රාජධානිය යටත් කරගන්නා ලදී (3 -> D). අනුපිළිවෙළ BAD වේ.', '1796 දී ඉංග්‍රීසීන් මුහුදුබඩ ප්‍රදේශ යටත් කරගත් අතර මුලින්ම පෙරදිග ඉන්දියා වෙළෙඳ සමාගම මගින් පාලනය ගෙන ගියේය (1 -> B). 1802 දී එම ප්‍රදේශ කෙළින්ම බ්‍රිතාන්‍ය කිරීටය යටතට පත් විය (2 -> A). 1815 දී උඩරට ගිවිසුම මගින් උඩරට රාජධානිය යටත් කරගන්නා ලදී (3 -> D). අනුපිළිවෙළ BAD වේ.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
