INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8b1b74a7-2b3a-4fc3-91cc-c67361f13588', 'bb4cca9d-4849-577a-a197-6aeab77cd286', 'මධ්‍යම බලවතුන්ගේ පිලේ සිටි ඉතාලිය මිත්‍ර පිලට එකතු වීම ය.', 'මධ්‍යම බලවතුන්ගේ පිලේ සිටි ඉතාලිය මිත්‍ර පිලට එකතු වීම ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2b95d6b6-df43-4a9c-9070-d5a203626f2e', 'bb4cca9d-4849-577a-a197-6aeab77cd286', 'බ්‍රිතාන්‍යයට ශක්තිමත් නාවුක බලයක් තිබීම ය.', 'බ්‍රිතාන්‍යයට ශක්තිමත් නාවුක බලයක් තිබීම ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fa43b310-fd0d-435f-9626-0d42acd855c2', 'bb4cca9d-4849-577a-a197-6aeab77cd286', 'ජර්මන් නාවුක හමුදාව තම අධිරාජයාට විරුද්ධව කැරලි ගැසීම ය.', 'ජර්මන් නාවුක හමුදාව තම අධිරාජයාට විරුද්ධව කැරලි ගැසීම ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7e3836d5-0c2d-55a3-9244-fc73557ef0a7', '9548b718-47d5-5969-a03d-ceaebef2631d', 35, '<p>එක්සත් ජාතීන්ගේ සංවිධානයේ සියලුම සාමාජික රටවල් නියෝජනය කරන ප්‍රධාන ආයතනය කුමක්ද?</p>', '<p>එක්සත් ජාතීන්ගේ සංවිධානයේ සියලුම සාමාජික රටවල් නියෝජනය කරන ප්‍රධාන ආයතනය කුමක්ද?</p>', NULL, 'එක්සත් ජාතීන්ගේ සංවිධානයේ (UN) සියලුම සාමාජික රාජ්‍යයන් නියෝජනය කරන, සෑම රටකටම සමාන ඡන්ද අයිතියක් ඇති ප්‍රධානතම ප්‍රතිපත්ති සම්පාදක ආයතනය වන්නේ ''මහා මණ්ඩලය'' (General Assembly) යි.', 'එක්සත් ජාතීන්ගේ සංවිධානයේ (UN) සියලුම සාමාජික රාජ්‍යයන් නියෝජනය කරන, සෑම රටකටම සමාන ඡන්ද අයිතියක් ඇති ප්‍රධානතම ප්‍රතිපත්ති සම්පාදක ආයතනය වන්නේ ''මහා මණ්ඩලය'' (General Assembly) යි.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
