INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0fb212e0-1115-4771-ad1a-2f0923097af5', '7e3836d5-0c2d-55a3-9244-fc73557ef0a7', 'ආර්ථික හා සමාජීය මණ්ඩලය', 'ආර්ථික හා සමාජීය මණ්ඩලය', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('88d641f6-dab4-584a-ae47-26a84ab929a6', '9548b718-47d5-5969-a03d-ceaebef2631d', 36, '<p>පළමුවන ලෝක යුද්ධයෙන් පසු වර්සෙල්ස් ගිවිසුම මගින් දැඩි දඬුවම්වලට භාජනය කළ රට කුමක්ද?</p>', '<p>පළමුවන ලෝක යුද්ධයෙන් පසු වර්සෙල්ස් ගිවිසුම මගින් දැඩි දඬුවම්වලට භාජනය කළ රට කුමක්ද?</p>', NULL, '1919 වර්සෙල්ස් ගිවිසුම (Treaty of Versailles) මගින් පළමුවන ලෝක යුද්ධයේ වගකීම සම්පූර්ණයෙන්ම ජර්මනිය මත පැටවූ අතර, භූමිය අහිමි කිරීම් සහ අධික යුද වන්දි ගෙවීම් ඇතුළු දැඩි දඬුවම් ජර්මනියට පනවනු ලැබීය.', '1919 වර්සෙල්ස් ගිවිසුම (Treaty of Versailles) මගින් පළමුවන ලෝක යුද්ධයේ වගකීම සම්පූර්ණයෙන්ම ජර්මනිය මත පැටවූ අතර, භූමිය අහිමි කිරීම් සහ අධික යුද වන්දි ගෙවීම් ඇතුළු දැඩි දඬුවම් ජර්මනියට පනවනු ලැබීය.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
