INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5249fa6e-215c-5a55-b8da-0aa942cff376', '98c89086-e7aa-587a-a970-649b525846a9', 26, '<p>ත්‍රිකෝණයක කෝණ දෙකක් 43^{\circ}$ සහ 53^{\circ}$ වේ. එහි තුන්වන කෝණයේ අගය සොයන්න.</p>', '<p>ත්‍රිකෝණයක කෝණ දෙකක් 43^{\circ}$ සහ 53^{\circ}$ වේ. එහි තුන්වන කෝණයේ අගය සොයන්න.</p>', NULL, '<p>ත්‍රිකෝණයක අභ්‍යන්තර කෝණවල ඓක්‍යය $180^{\circ}$ වේ. එබැවින් $180 - (43 + 53) = 84^{\circ}$.</p>', '<p>ත්‍රිකෝණයක අභ්‍යන්තර කෝණවල ඓක්‍යය $180^{\circ}$ වේ. එබැවින් $180 - (43 + 53) = 84^{\circ}$.</p>', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
