INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('79904926-4751-5484-9a19-a45908e16d47', '98c89086-e7aa-587a-a970-649b525846a9', 29, '<p>$3^3 \times 3^2$ සුළු කරන්න.</p>', '<p>$3^3 \times 3^2$ සුළු කරන්න.</p>', NULL, '<p>දර්ශක නීති වලට අනුව, $a^m \times a^n = a^{m+n}$. එබැවින් $3^3 \times 3^2 = 3^{3+2} = 3^5$.</p>', '<p>දර්ශක නීති වලට අනුව, $a^m \times a^n = a^{m+n}$. එබැවින් $3^3 \times 3^2 = 3^{3+2} = 3^5$.</p>', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8e57e478-3bc4-4da8-bc8f-954b021fd032', '79904926-4751-5484-9a19-a45908e16d47', '$3^5$', '$3^5$', NULL, 'sanitized', 'v1', 0, 1);
