INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5a026e53-d8d7-5798-8b53-e69f8702050e', '98c89086-e7aa-587a-a970-649b525846a9', 47, '<p>දිග 8 cm හා පළල 5 cm වූ සෘජුකෝණාස්‍රයක වර්ගඵලය සොයන්න.</p>', '<p>දිග 8 cm හා පළල 5 cm වූ සෘජුකෝණාස්‍රයක වර්ගඵලය සොයන්න.</p>', NULL, '<p>වර්ගඵලය = දිග $\times$ පළල = $8 \times 5 = 40 \text{ cm}^2$.</p>', '<p>වර්ගඵලය = දිග $\times$ පළල = $8 \times 5 = 40 \text{ cm}^2$.</p>', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
