INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('42d1f26d-041a-588a-af57-0a1077e21310', '98c89086-e7aa-587a-a970-649b525846a9', 48, '<p>$3, 5, 7, 9$ යන සංඛ්‍යා වල මධ්‍යන්‍යය සොයන්න.</p>', '<p>$3, 5, 7, 9$ යන සංඛ්‍යා වල මධ්‍යන්‍යය සොයන්න.</p>', NULL, '<p>මධ්‍යන්‍යය = $\frac{3 + 5 + 7 + 9}{4} = \frac{24}{4} = 6$.</p>', '<p>මධ්‍යන්‍යය = $\frac{3 + 5 + 7 + 9}{4} = \frac{24}{4} = 6$.</p>', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
