INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5c21d006-0717-46bb-b55c-937ee3409eb4', 'b4fff736-24a2-5589-93e0-6f19618495ac', 'හෙන්රි මෝස්ලි.', 'හෙන්රි මෝස්ලි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3cba0e5b-8c76-58d9-89f0-9ee1722b7fe9', '9dd2faee-abf5-56af-893b-8ac4c1c0af6c', 2, '<p>පහත අණු සම්බන්ධයෙන් මින් කුමන වගන්තිය අසත්‍ය වන්නේද?<br><br>$CO_2$, $BF_3$, $PF_3$, $CF_4$, $XeF_4$, $SF_6$</p>', '<p>පහත අණු සම්බන්ධයෙන් මින් කුමන වගන්තිය අසත්‍ය වන්නේද?<br><br>$CO_2$, $BF_3$, $PF_3$, $CF_4$, $XeF_4$, $SF_6$</p>', NULL, 'මෙහිදී අසත්‍ය වගන්තිය ඇසෙයි. $PF_3$ අණුව ධ්‍රැවීය වේ (කේන්ද්‍රීය පරමාණුව මත එකසර යුගලයක් පවතී). එබැවින් ''සියලුම අණු නිර්ධ්‍රැවීය වේ'' යන (4) වගන්තිය අසත්‍ය වේ. තවද $CO_2$ සහ $CF_4$ යන අණු අෂ්ටක නීතිය අනුගමනය කරයි. එබැවින් ''සියලුම අණු අෂ්ටක නීතිය අනුගමනය නොකරයි'' යන (3) වගන්තිය ද අසත්‍ය වේ.<br><br>(සටහන: ලකුණු දීමේ පටිපාටියට අනුව 3 සහ 4 යන දෙකම නිවැරදි පිළිතුරු ලෙස සලකා ඇත. මෙහිදී අප 3 වන පිළිතුර දක්වා ඇත).', 'මෙහිදී අසත්‍ය වගන්තිය ඇසෙයි. $PF_3$ අණුව ධ්‍රැවීය වේ (කේන්ද්‍රීය පරමාණුව මත එකසර යුගලයක් පවතී). එබැවින් ''සියලුම අණු නිර්ධ්‍රැවීය වේ'' යන (4) වගන්තිය අසත්‍ය වේ. තවද $CO_2$ සහ $CF_4$ යන අණු අෂ්ටක නීතිය අනුගමනය කරයි. එබැවින් ''සියලුම අණු අෂ්ටක නීතිය අනුගමනය නොකරයි'' යන (3) වගන්තිය ද අසත්‍ය වේ.<br><br>(සටහන: ලකුණු දීමේ පටිපාටියට අනුව 3 සහ 4 යන දෙකම නිවැරදි පිළිතුරු ලෙස සලකා ඇත. මෙහිදී අප 3 වන පිළිතුර දක්වා ඇත).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('101ca75f-4435-4118-a764-4c0983514059', '3cba0e5b-8c76-58d9-89f0-9ee1722b7fe9', 'සියලු ම අණුවලට ධ්‍රැවීය සහසංයුජ බන්ධන ඇත.', 'සියලු ම අණුවලට ධ්‍රැවීය සහසංයුජ බන්ධන ඇත.', NULL, 'sanitized', 'v1', 0, 1);
