INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f67f8689-6550-4756-8608-e05b749218af', '3cba0e5b-8c76-58d9-89f0-9ee1722b7fe9', 'සියලු ම අණු නිර්ධ්‍රැවීය වේ.', 'සියලු ම අණු නිර්ධ්‍රැවීය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('404525c7-247b-4f38-bdec-d39bb424b0ac', '3cba0e5b-8c76-58d9-89f0-9ee1722b7fe9', 'අණු දෙකක පමණක් ඒවායෙහි මධ්‍ය පරමාණු සතුව එකසර ඉලෙක්ට්‍රෝන යුගල් පවතී.', 'අණු දෙකක පමණක් ඒවායෙහි මධ්‍ය පරමාණු සතුව එකසර ඉලෙක්ට්‍රෝන යුගල් පවතී.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6e02cac5-6e3b-5b3d-bb86-dbac955123b2', '9dd2faee-abf5-56af-893b-8ac4c1c0af6c', 3, '<p>පහත දැක්වෙන සංයෝගයේ IUPAC නාමය කුමක්ද?<br><br>$$H-C \equiv C - CH(OH) - CH(CH_2CH_3) - CH_2 - CHO$$</p>', '<p>පහත දැක්වෙන සංයෝගයේ IUPAC නාමය කුමක්ද?<br><br>$$H-C \equiv C - CH(OH) - CH(CH_2CH_3) - CH_2 - CHO$$</p>', NULL, 'ප්‍රධාන ක්‍රියාකාරී කාණ්ඩය ඇල්ඩිහයිඩ් ($-CHO$) කාණ්ඩය වන බැවින් එයට අංක 1 ලැබෙන සේ කාබන් දාමය අංකනය කළ යුතුය. එමෙන්ම ද්විත්ව/ත්‍රිත්ව බන්ධන ප්‍රධාන දාමයට ඇතුළත් විය යුතුය. මේ අනුව ප්‍රධාන දාමය කාබන් පරමාණු 5කින් සමන්විත (pent) වේ. 2-වන කාබන්හි ඉතිල් කාණ්ඩයක් ද, 3-වන කාබන්හි හයිඩ්‍රොක්සි කාණ්ඩයක් ද, 4-වන කාබන්හි ත්‍රිත්ව බන්ධනයක් ද පිහිටයි. එබැවින් IUPAC නාමය 2-ethyl-3-hydroxypent-4-ynal වේ.', 'ප්‍රධාන ක්‍රියාකාරී කාණ්ඩය ඇල්ඩිහයිඩ් ($-CHO$) කාණ්ඩය වන බැවින් එයට අංක 1 ලැබෙන සේ කාබන් දාමය අංකනය කළ යුතුය. එමෙන්ම ද්විත්ව/ත්‍රිත්ව බන්ධන ප්‍රධාන දාමයට ඇතුළත් විය යුතුය. මේ අනුව ප්‍රධාන දාමය කාබන් පරමාණු 5කින් සමන්විත (pent) වේ. 2-වන කාබන්හි ඉතිල් කාණ්ඩයක් ද, 3-වන කාබන්හි හයිඩ්‍රොක්සි කාණ්ඩයක් ද, 4-වන කාබන්හි ත්‍රිත්ව බන්ධනයක් ද පිහිටයි. එබැවින් IUPAC නාමය 2-ethyl-3-hydroxypent-4-ynal වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
