INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('9fa7f4e9-404a-514d-9451-b766dfd2b431', '9dd2faee-abf5-56af-893b-8ac4c1c0af6c', 4, '<p>නයිට්‍රජන්හි ඔක්සිකරණ අවස්ථාව - 1 වන්නේ,</p>', '<p>නයිට්‍රජන්හි ඔක්සිකරණ අවස්ථාව - 1 වන්නේ,</p>', NULL, '$NH_2OH$ හි නයිට්‍රජන්ගේ ඔක්සිකරණ අංකය සෙවීම:<br>$x + 2(+1) + (-2) + (+1) = 0 \Rightarrow x + 1 = 0 \Rightarrow x = -1$.<br>අනෙක් අණුවල N හි ඔක්සිකරණ අංක: $N_2O_4$ (+4), $N_2O$ (+1), $NO_2F$ (+5), $NH_3$ (-3) වේ.', '$NH_2OH$ හි නයිට්‍රජන්ගේ ඔක්සිකරණ අංකය සෙවීම:<br>$x + 2(+1) + (-2) + (+1) = 0 \Rightarrow x + 1 = 0 \Rightarrow x = -1$.<br>අනෙක් අණුවල N හි ඔක්සිකරණ අංක: $N_2O_4$ (+4), $N_2O$ (+1), $NO_2F$ (+5), $NH_3$ (-3) වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
