INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('65ad2e2e-ba2f-4a6d-b4d4-6c0b302eda99', 'fbd099ee-0fb5-5e06-b3e1-90a921ec9048', 'රේඛීය, ක්‍රියානති පිරමිඩාකාර, T -හැඩය.', 'රේඛීය, ක්‍රියානති පිරමිඩාකාර, T -හැඩය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9bf8be83-379a-415b-bb3f-e4188ff18800', 'fbd099ee-0fb5-5e06-b3e1-90a921ec9048', 'තලීය ත්‍රිකෝණාකාර, කෝණික, T -හැඩය.', 'තලීය ත්‍රිකෝණාකාර, කෝණික, T -හැඩය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5efaa216-49f1-4d77-9c2f-0fc037b1255d', 'fbd099ee-0fb5-5e06-b3e1-90a921ec9048', 'රේඛීය, තලීය ත්‍රිකෝණාකාර, සී - සෝ.', 'රේඛීය, තලීය ත්‍රිකෝණාකාර, සී - සෝ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a0528067-1b84-5ce7-a810-f875199872ae', '9dd2faee-abf5-56af-893b-8ac4c1c0af6c', 6, '<p>ඇමෝනියම් නයිට්‍රේට් ඉහළ උෂ්ණත්වයේ දී, නයිට්‍රජන් වායුව, ඔක්සිජන් වායුව හා ජල වාෂ්ප සාදමින් ස්ඵෝටික ලෙස වියෝජනය වේ. සම්මත උෂ්ණත්වයේ දී හා පීඩනයේ දී ඇමෝනියම් නයිට්‍රේට් 240 g වියෝජනය වීමෙන් සෑදෙන මුළු වායු ලීටර සංඛ්‍යාව වනුයේ,<br><br>($H=1$, $N=14$, $O=16$, සම්මත උෂ්ණත්වයේ දී හා පීඩනයේ දී වායු මවුල එකක පරිමාව ලීටර 22.4 වේ.)</p>', '<p>ඇමෝනියම් නයිට්‍රේට් ඉහළ උෂ්ණත්වයේ දී, නයිට්‍රජන් වායුව, ඔක්සිජන් වායුව හා ජල වාෂ්ප සාදමින් ස්ඵෝටික ලෙස වියෝජනය වේ. සම්මත උෂ්ණත්වයේ දී හා පීඩනයේ දී ඇමෝනියම් නයිට්‍රේට් 240 g වියෝජනය වීමෙන් සෑදෙන මුළු වායු ලීටර සංඛ්‍යාව වනුයේ,<br><br>($H=1$, $N=14$, $O=16$, සම්මත උෂ්ණත්වයේ දී හා පීඩනයේ දී වායු මවුල එකක පරිමාව ලීටර 22.4 වේ.)</p>', NULL, 'තුලිත රසායනික සමීකරණය: $2NH_4NO_3(s) \rightarrow 2N_2(g) + O_2(g) + 4H_2O(g)$<br>$NH_4NO_3$ මවුලික ස්කන්ධය = $80~g~mol^{-1}$<br>$NH_4NO_3$ මවුල ගණන = $240~g / 80~g~mol^{-1} = 3~mol$<br>STP හිදී ජලය ද්‍රවයක් බැවින්, සෑදෙන ජලය ඝනීභවනය වේ යැයි සැලකූ විට ඉතිරි වායු මවුල ගණන ($N_2$ සහ $O_2$ පමණක්) = $3 \times (3/2) = 4.5~mol$.<br>එවිට පරිමාව = $4.5 \times 22.4~L = 100.8~L$ (3 වන පිළිතුර).<br><br>(සටහන: ජලය වාෂ්පයක් ලෙස සැලකුවහොත් මුළු පරිමාව $235.2~L$ (5 වන පිළිතුර) වේ. ප්‍රතික්‍රියාව $N_2O$ සාදන ලෙස ගත් විට $67.2~L$ (2 වන පිළිතුර) වේ. ලකුණු දීමේ පටිපාටියෙහි 2, 3 සහ 5 යන පිළිතුරු තුනම නිවැරදි ලෙස සලකා ඇත).', 'තුලිත රසායනික සමීකරණය: $2NH_4NO_3(s) \rightarrow 2N_2(g) + O_2(g) + 4H_2O(g)$<br>$NH_4NO_3$ මවුලික ස්කන්ධය = $80~g~mol^{-1}$<br>$NH_4NO_3$ මවුල ගණන = $240~g / 80~g~mol^{-1} = 3~mol$<br>STP හිදී ජලය ද්‍රවයක් බැවින්, සෑදෙන ජලය ඝනීභවනය වේ යැයි සැලකූ විට ඉතිරි වායු මවුල ගණන ($N_2$ සහ $O_2$ පමණක්) = $3 \times (3/2) = 4.5~mol$.<br>එවිට පරිමාව = $4.5 \times 22.4~L = 100.8~L$ (3 වන පිළිතුර).<br><br>(සටහන: ජලය වාෂ්පයක් ලෙස සැලකුවහොත් මුළු පරිමාව $235.2~L$ (5 වන පිළිතුර) වේ. ප්‍රතික්‍රියාව $N_2O$ සාදන ලෙස ගත් විට $67.2~L$ (2 වන පිළිතුර) වේ. ලකුණු දීමේ පටිපාටියෙහි 2, 3 සහ 5 යන පිළිතුරු තුනම නිවැරදි ලෙස සලකා ඇත).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
