INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7f7b2971-e16f-46a1-aa07-11bef6588b44', '601620a7-ee88-5a86-b662-1d851046c713', '$p^2=q$', '$p^2=q$', NULL, 'sanitized', 'v1', 1, 0);
