INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2aa72466-d832-4b83-9879-5ead2e5eb244', '601620a7-ee88-5a86-b662-1d851046c713', '$p=2q^2$', '$p=2q^2$', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('a66f879e-ed91-5d6a-8a71-6efc8c496f79', '9dd2faee-abf5-56af-893b-8ac4c1c0af6c', 8, '<p>ක්ෂාර හා ක්ෂාරීය පාංශු ලෝහ සම්බන්ධයෙන් මින් කුමන වගන්තිය අසත්‍ය වේ ද?</p>', '<p>ක්ෂාර හා ක්ෂාරීය පාංශු ලෝහ සම්බන්ධයෙන් මින් කුමන වගන්තිය අසත්‍ය වේ ද?</p>', NULL, 'මෙම ප්‍රශ්නයට අදාළව 3 වන වගන්තිය අසත්‍ය වේ, මන්ද $Be(OH)_2$ උභයගුණී වන අතර $Mg(OH)_2$ දුබල භස්මයක් වේ. එහෙත් විභාග දෙපාර්තමේන්තුවේ නිල ලකුණු දීමේ පටිපාටියට අනුව පිළිතුර 4 ලෙස දක්වා ඇත. ක්ෂාර ලෝහවල දෙවන අයනීකරණ ශක්තීන් (උදා: $Na^+ \rightarrow Na^{2+}$) උච්ච වායු වින්‍යාසයකින් ඉලෙක්ට්‍රෝනයක් ඉවත් කළ යුතු බැවින් ඒවා ක්ෂාරීය පාංශු ලෝහවල අගයයන්ට වඩා බොහෝ වැඩි වේ. එබැවින් 4 වන වගන්තිය සැබවින්ම සත්‍ය ප්‍රකාශයකි.', 'මෙම ප්‍රශ්නයට අදාළව 3 වන වගන්තිය අසත්‍ය වේ, මන්ද $Be(OH)_2$ උභයගුණී වන අතර $Mg(OH)_2$ දුබල භස්මයක් වේ. එහෙත් විභාග දෙපාර්තමේන්තුවේ නිල ලකුණු දීමේ පටිපාටියට අනුව පිළිතුර 4 ලෙස දක්වා ඇත. ක්ෂාර ලෝහවල දෙවන අයනීකරණ ශක්තීන් (උදා: $Na^+ \rightarrow Na^{2+}$) උච්ච වායු වින්‍යාසයකින් ඉලෙක්ට්‍රෝනයක් ඉවත් කළ යුතු බැවින් ඒවා ක්ෂාරීය පාංශු ලෝහවල අගයයන්ට වඩා බොහෝ වැඩි වේ. එබැවින් 4 වන වගන්තිය සැබවින්ම සත්‍ය ප්‍රකාශයකි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('64763172-95c8-40ff-98ad-985ff877c08e', 'a66f879e-ed91-5d6a-8a71-6efc8c496f79', 'සියලුම ක්ෂාරීය පාංශු ලෝහ $N_2$ වායුව සමග ඉහළ උෂ්ණත්වයේ දී ප්‍රතික්‍රියා කරයි.', 'සියලුම ක්ෂාරීය පාංශු ලෝහ $N_2$ වායුව සමග ඉහළ උෂ්ණත්වයේ දී ප්‍රතික්‍රියා කරයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('25d77e7e-3046-412c-a56e-663d3ef5ede9', 'a66f879e-ed91-5d6a-8a71-6efc8c496f79', 'ක්ෂාරීය පාංශු ලෝහවල ද්‍රවාංක එම ආවර්තයේම ඇති ක්ෂාර ලෝහවල ද්‍රවාංක වලට වඩා වැඩි ය.', 'ක්ෂාරීය පාංශු ලෝහවල ද්‍රවාංක එම ආවර්තයේම ඇති ක්ෂාර ලෝහවල ද්‍රවාංක වලට වඩා වැඩි ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7e9169a4-61d6-4df4-aedd-46a6ad272469', 'a66f879e-ed91-5d6a-8a71-6efc8c496f79', 'ක්ෂාරීය පාංශු ලෝහ සාදන සියලු ම හයිඩ්‍රොක්සයිඩ ප්‍රබල භස්ම වේ.', 'ක්ෂාරීය පාංශු ලෝහ සාදන සියලු ම හයිඩ්‍රොක්සයිඩ ප්‍රබල භස්ම වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ad3bccfc-bed8-41bf-8774-65ccbdd7a299', 'a66f879e-ed91-5d6a-8a71-6efc8c496f79', 'ක්ෂාර ලෝහවල දෙවන අයනීකරණ ශක්තීන් එම ආවර්තයේම ඇති ක්ෂාරීය පාංශු ලෝහ වල එම අගයයන්ට වඩා බොහෝ වැඩි ය.', 'ක්ෂාර ලෝහවල දෙවන අයනීකරණ ශක්තීන් එම ආවර්තයේම ඇති ක්ෂාරීය පාංශු ලෝහ වල එම අගයයන්ට වඩා බොහෝ වැඩි ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f1de1bc3-eae2-4f88-af35-3119387e0609', 'a66f879e-ed91-5d6a-8a71-6efc8c496f79', 'ක්ෂාර ලෝහ හයිඩ්‍රොක්සයිඩවල ද්‍රාව්‍යතාව කාණ්ඩයේ පහළට වැඩි වේ.', 'ක්ෂාර ලෝහ හයිඩ්‍රොක්සයිඩවල ද්‍රාව්‍යතාව කාණ්ඩයේ පහළට වැඩි වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6e699967-fd99-56c3-b40e-1965b691c4f1', '9dd2faee-abf5-56af-893b-8ac4c1c0af6c', 9, '<p>ලිතියම්හි (Li) සංයුජතා ඉලෙක්ට්‍රෝනයට දැනෙන සඵල න්‍යෂ්ටික ආරෝපණය,<br>(Li, $Z=3$ හා සාපේක්ෂ පරමාණුක ස්කන්ධය = 7)</p>', '<p>ලිතියම්හි (Li) සංයුජතා ඉලෙක්ට්‍රෝනයට දැනෙන සඵල න්‍යෂ්ටික ආරෝපණය,<br>(Li, $Z=3$ හා සාපේක්ෂ පරමාණුක ස්කන්ධය = 7)</p>', NULL, 'Li හි සැබෑ න්‍යෂ්ටික ආරෝපණය +3 වේ ($Z=3$ බැවින්). නමුත් එහි සංයුජතා ඉලෙක්ට්‍රෝනය ($2s^1$) අභ්‍යන්තර ඉලෙක්ට්‍රෝන කවචය ($1s^2$) මගින් ආවරණය (shielding effect) වීම හේතුවෙන් ඊට දැනෙන සඵල න්‍යෂ්ටික ආරෝපණය (effective nuclear charge, $Z_{eff}$) සැබෑ න්‍යෂ්ටික ආරෝපණයට (+3) වඩා අඩු වේ.', 'Li හි සැබෑ න්‍යෂ්ටික ආරෝපණය +3 වේ ($Z=3$ බැවින්). නමුත් එහි සංයුජතා ඉලෙක්ට්‍රෝනය ($2s^1$) අභ්‍යන්තර ඉලෙක්ට්‍රෝන කවචය ($1s^2$) මගින් ආවරණය (shielding effect) වීම හේතුවෙන් ඊට දැනෙන සඵල න්‍යෂ්ටික ආරෝපණය (effective nuclear charge, $Z_{eff}$) සැබෑ න්‍යෂ්ටික ආරෝපණයට (+3) වඩා අඩු වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
