INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('150dfbb1-b9e3-4507-b0f6-a1478c9da3de', 'e97ba3dc-aa0e-5ccf-a518-b3e5218e6803', 'පද්ධතියේ ඇති $SO_2(g)$ ප්‍රමාණය', 'පද්ධතියේ ඇති $SO_2(g)$ ප්‍රමාණය', NULL, 'sanitized', 'v1', 2, 0);
