INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b6c5129a-7c9c-5598-9624-ce2bec638520', '9dd2faee-abf5-56af-893b-8ac4c1c0af6c', 20, '<p>සල්ෆර් සහ එහි සංයෝග සම්බන්ධයෙන් පහත සඳහන් කුමන වගන්තිය අසත්‍ය වන්නේ ද?</p>', '<p>සල්ෆර් සහ එහි සංයෝග සම්බන්ධයෙන් පහත සඳහන් කුමන වගන්තිය අසත්‍ය වන්නේ ද?</p>', NULL, 'සල්ෆර් (S) සාන්ද්‍ර සල්ෆියුරික් අම්ලය ($H_2SO_4$) සමඟ ප්‍රතික්‍රියා කිරීමේදී සෑදෙන්නේ සල්ෆර් ඩයොක්සයිඩ් ($SO_2$) වායුව සහ ජලයයි. එනම් $S + 2H_2SO_4 \rightarrow 3SO_2 + 2H_2O$ වේ. එහිදී $SO_3$ ඵලයක් ලෙස නොසෑදෙන බැවින් දෙවන වගන්තිය අසත්‍ය වේ.', 'සල්ෆර් (S) සාන්ද්‍ර සල්ෆියුරික් අම්ලය ($H_2SO_4$) සමඟ ප්‍රතික්‍රියා කිරීමේදී සෑදෙන්නේ සල්ෆර් ඩයොක්සයිඩ් ($SO_2$) වායුව සහ ජලයයි. එනම් $S + 2H_2SO_4 \rightarrow 3SO_2 + 2H_2O$ වේ. එහිදී $SO_3$ ඵලයක් ලෙස නොසෑදෙන බැවින් දෙවන වගන්තිය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('be8604be-ee39-4bf9-98b0-c222d5014a2a', 'b6c5129a-7c9c-5598-9624-ce2bec638520', 'S යනු ඔක්සිකරණ අවස්ථා -2 සිට +6 පරාසයක් ඇති අලෝහයකි.', 'S යනු ඔක්සිකරණ අවස්ථා -2 සිට +6 පරාසයක් ඇති අලෝහයකි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7e5eddbd-50d9-457e-b019-22b32580eaa5', 'b6c5129a-7c9c-5598-9624-ce2bec638520', 'එක් ඵලයක් ලෙස $SO_3$ ලබා දෙමින් සාන්ද්‍ර $H_2SO_4$ සමග S ප්‍රතික්‍රියා කරයි.', 'එක් ඵලයක් ලෙස $SO_3$ ලබා දෙමින් සාන්ද්‍ර $H_2SO_4$ සමග S ප්‍රතික්‍රියා කරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('99945946-0e33-4e9b-8365-0f22361a92ee', 'b6c5129a-7c9c-5598-9624-ce2bec638520', 'ඔක්සිකාරකයක් සහ ඔක්සිහාරකයක් යන දෙආකාරයටම $SO_2$ ට ක්‍රියා කළ හැක.', 'ඔක්සිකාරකයක් සහ ඔක්සිහාරකයක් යන දෙආකාරයටම $SO_2$ ට ක්‍රියා කළ හැක.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('262d5c69-2db2-4b57-bc19-f0cd3e38ca56', 'b6c5129a-7c9c-5598-9624-ce2bec638520', 'විශාල ප්‍රමාණයන්ගෙන් S දහනය කිරීම අම්ල වැසි වලට දායක වේ.', 'විශාල ප්‍රමාණයන්ගෙන් S දහනය කිරීම අම්ල වැසි වලට දායක වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e8f9a97a-1dd9-4623-b766-809190bcf0f5', 'b6c5129a-7c9c-5598-9624-ce2bec638520', 'සාන්ද්‍ර $H_2SO_4$ ට ප්‍රබල අම්ලයක්, ඔක්සිකාරකයක් සහ විජලකාරකයක් ලෙස ක්‍රියා කළ හැක.', 'සාන්ද්‍ර $H_2SO_4$ ට ප්‍රබල අම්ලයක්, ඔක්සිකාරකයක් සහ විජලකාරකයක් ලෙස ක්‍රියා කළ හැක.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('af25aae9-d92d-53c2-9101-aecfe9a95407', '9dd2faee-abf5-56af-893b-8ac4c1c0af6c', 21, '<p>298 K හි දී $N_2(g) + 3F_2(g) \rightarrow 2NF_3(g)$ ප්‍රතික්‍රියාවේ සම්මත එන්තැල්පි විපර්යාසය $\Delta H^{\circ} = -263 \text{ kJ mol}^{-1}$ වේ. $N \equiv N$ හා $N-F$ බන්ධන වල බන්ධන විඝටන එන්තැල්පි අගයයන් පිළිවෙළින් 946 kJ $mol^{-1}$ හා 272 kJ $mol^{-1}$ වේ. $F-F$ බන්ධනයේ බන්ධන විඝටන එන්තැල්පි අගය (kJ $mol^{-1}$ වලින්) වනුයේ,</p>', '<p>298 K හි දී $N_2(g) + 3F_2(g) \rightarrow 2NF_3(g)$ ප්‍රතික්‍රියාවේ සම්මත එන්තැල්පි විපර්යාසය $\Delta H^{\circ} = -263 \text{ kJ mol}^{-1}$ වේ. $N \equiv N$ හා $N-F$ බන්ධන වල බන්ධන විඝටන එන්තැල්පි අගයයන් පිළිවෙළින් 946 kJ $mol^{-1}$ හා 272 kJ $mol^{-1}$ වේ. $F-F$ බන්ධනයේ බන්ධන විඝටන එන්තැල්පි අගය (kJ $mol^{-1}$ වලින්) වනුයේ,</p>', NULL, 'ප්‍රතික්‍රියාවේ එන්තැල්පි විපර්යාසය ($\Delta H$) පහත පරිදි ගණනය කළ හැක:<br>$\Delta H = \sum \text{බන්ධන ශක්ති (ප්‍රතික්‍රියක)} - \sum \text{බන්ධන ශක්ති (ඵල)}$<br>$-263 = [\text{B.E.}(N \equiv N) + 3 \times \text{B.E.}(F-F)] - [2 \times 3 \times \text{B.E.}(N-F)]$<br>$-263 = [946 + 3x] - [6 \times 272]$<br>$-263 = 946 + 3x - 1632$<br>$-263 = 3x - 686$<br>$3x = 686 - 263 = 423$<br>$x = 141 \text{ kJ mol}^{-1}$', 'ප්‍රතික්‍රියාවේ එන්තැල්පි විපර්යාසය ($\Delta H$) පහත පරිදි ගණනය කළ හැක:<br>$\Delta H = \sum \text{බන්ධන ශක්ති (ප්‍රතික්‍රියක)} - \sum \text{බන්ධන ශක්ති (ඵල)}$<br>$-263 = [\text{B.E.}(N \equiv N) + 3 \times \text{B.E.}(F-F)] - [2 \times 3 \times \text{B.E.}(N-F)]$<br>$-263 = [946 + 3x] - [6 \times 272]$<br>$-263 = 946 + 3x - 1632$<br>$-263 = 3x - 686$<br>$3x = 686 - 263 = 423$<br>$x = 141 \text{ kJ mol}^{-1}$', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
