INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cd158ba2-4807-5aed-87d7-48c759c09c0e', '9dd2faee-abf5-56af-893b-8ac4c1c0af6c', 22, '<p>3d - ගොනුවේ මූල ද්‍රව්‍ය සම්බන්ධයෙන් පහත කුමන වගන්තිය අසත්‍ය වේ ද?</p>', '<p>3d - ගොනුවේ මූල ද්‍රව්‍ය සම්බන්ධයෙන් පහත කුමන වගන්තිය අසත්‍ය වේ ද?</p>', NULL, 'ස්කැන්ඩියම් (Sc, +3 පමණි) සහ සින්ක් (Zn, +2 පමණි) විචල්‍ය ඔක්සිකරණ අවස්ථා නොපෙන්වන බව සත්‍යයකි. නමුත් ටයිටේනියම් (Ti) මූලද්‍රව්‍යය +2, +3, සහ +4 යන ඔක්සිකරණ අවස්ථා (විචල්‍ය සංයුජතා) ප්‍රදර්ශනය කරයි. එබැවින් මෙම ප්‍රකාශය අසත්‍ය වේ.', 'ස්කැන්ඩියම් (Sc, +3 පමණි) සහ සින්ක් (Zn, +2 පමණි) විචල්‍ය ඔක්සිකරණ අවස්ථා නොපෙන්වන බව සත්‍යයකි. නමුත් ටයිටේනියම් (Ti) මූලද්‍රව්‍යය +2, +3, සහ +4 යන ඔක්සිකරණ අවස්ථා (විචල්‍ය සංයුජතා) ප්‍රදර්ශනය කරයි. එබැවින් මෙම ප්‍රකාශය අසත්‍ය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ea33eeb9-8760-4eb7-9a8a-92a9f6c90e4a', 'cd158ba2-4807-5aed-87d7-48c759c09c0e', 'Sc, Ti සහ Zn විචල්‍ය සංයුජතා ප්‍රදර්ශනය නොකරයි.', 'Sc, Ti සහ Zn විචල්‍ය සංයුජතා ප්‍රදර්ශනය නොකරයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('029cc17a-bb5b-4245-bce6-eb4d9d5a9d1f', 'cd158ba2-4807-5aed-87d7-48c759c09c0e', '3d - ගොනුවේ මූල ද්‍රව්‍ය හොඳ කාර්මික උත්ප්‍රේරක වේ.', '3d - ගොනුවේ මූල ද්‍රව්‍ය හොඳ කාර්මික උත්ප්‍රේරක වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1d90c2a5-4269-408a-bf81-0671fad71449', 'cd158ba2-4807-5aed-87d7-48c759c09c0e', 'Mn, ආම්ලික, උභයගුණී සහ භාස්මික ඔක්සයිඩ සාදයි.', 'Mn, ආම්ලික, උභයගුණී සහ භාස්මික ඔක්සයිඩ සාදයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('29284df6-af1a-4bb7-abfd-3a8b5c44971c', 'cd158ba2-4807-5aed-87d7-48c759c09c0e', '3d -ගොනුවේ සියලු ම මුල ද්‍රව්‍ය අතුරෙන් අඩුම ද්‍රවාංකය ඇත්තේ Zn ට ය.', '3d -ගොනුවේ සියලු ම මුල ද්‍රව්‍ය අතුරෙන් අඩුම ද්‍රවාංකය ඇත්තේ Zn ට ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b8897159-b831-4f54-b904-f98769f91f44', 'cd158ba2-4807-5aed-87d7-48c759c09c0e', 'V හි ධන ඔක්සිකරණ අවස්ථා +2 සිට +5 පරාසයක ඇත.', 'V හි ධන ඔක්සිකරණ අවස්ථා +2 සිට +5 පරාසයක ඇත.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('178f496d-ea38-571e-b66f-78be3be292a4', '9dd2faee-abf5-56af-893b-8ac4c1c0af6c', 23, '<p>$3NO(g) \rightleftharpoons NO_2(g) + N_2O(g)$ ප්‍රතික්‍රියාව සඳහා පහත තාප රසායනික දත්ත දී ඇත.<br>$\Delta H_{f_{NO_2(g)}}^{\circ} = 35 \text{ kJ mol}^{-1}$, $\Delta H_{f_{N_2O(g)}}^{\circ} = 80 \text{ kJ mol}^{-1}$, $\Delta H_{f_{NO(g)}}^{\circ} = 90 \text{ kJ mol}^{-1}$<br>ඉහත ප්‍රතික්‍රියාව සඳහා සඳහන් කුමන ප්‍රකාශය සත්‍ය වේද?</p>', '<p>$3NO(g) \rightleftharpoons NO_2(g) + N_2O(g)$ ප්‍රතික්‍රියාව සඳහා පහත තාප රසායනික දත්ත දී ඇත.<br>$\Delta H_{f_{NO_2(g)}}^{\circ} = 35 \text{ kJ mol}^{-1}$, $\Delta H_{f_{N_2O(g)}}^{\circ} = 80 \text{ kJ mol}^{-1}$, $\Delta H_{f_{NO(g)}}^{\circ} = 90 \text{ kJ mol}^{-1}$<br>ඉහත ප්‍රතික්‍රියාව සඳහා සඳහන් කුමන ප්‍රකාශය සත්‍ය වේද?</p>', NULL, 'සම්මත එන්තැල්පි විපර්යාසය: $\Delta H^{\circ} = \sum \Delta H_f^{\circ}(\text{ඵල}) - \sum \Delta H_f^{\circ}(\text{ප්‍රතික්‍රියක})$<br>$\Delta H^{\circ} = [35 + 80] - [3 \times 90] = 115 - 270 = -155 \text{ kJ mol}^{-1}$.<br>$\Delta H^{\circ}$ සෘණ අගයක් ගන්නා බැවින් මෙය තාපදායක ප්‍රතික්‍රියාවකි. ලෙ චැටලියර් මූලධර්මයට අනුව, තාපදායක ප්‍රතික්‍රියාවක උෂ්ණත්වය වැඩි කරන විට සමතුලිතය ආපසු හැරෙන (වමට බර වන) බැවින් සමතුලිතතා නියතය ($K_c$) අඩු වේ.', 'සම්මත එන්තැල්පි විපර්යාසය: $\Delta H^{\circ} = \sum \Delta H_f^{\circ}(\text{ඵල}) - \sum \Delta H_f^{\circ}(\text{ප්‍රතික්‍රියක})$<br>$\Delta H^{\circ} = [35 + 80] - [3 \times 90] = 115 - 270 = -155 \text{ kJ mol}^{-1}$.<br>$\Delta H^{\circ}$ සෘණ අගයක් ගන්නා බැවින් මෙය තාපදායක ප්‍රතික්‍රියාවකි. ලෙ චැටලියර් මූලධර්මයට අනුව, තාපදායක ප්‍රතික්‍රියාවක උෂ්ණත්වය වැඩි කරන විට සමතුලිතය ආපසු හැරෙන (වමට බර වන) බැවින් සමතුලිතතා නියතය ($K_c$) අඩු වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('77625d58-ab08-4ea9-84ac-704dd2ca59e9', '178f496d-ea38-571e-b66f-78be3be292a4', '$\Delta H^{\circ} = -155 \text{ kJ mol}^{-1}$ වන අතර උෂ්ණත්වය වැඩි වීමත් සමග ප්‍රතික්‍රියාවේ සමතුලිතතා නියතයේ අගය අඩු වේ.', '$\Delta H^{\circ} = -155 \text{ kJ mol}^{-1}$ වන අතර උෂ්ණත්වය වැඩි වීමත් සමග ප්‍රතික්‍රියාවේ සමතුලිතතා නියතයේ අගය අඩු වේ.', NULL, 'sanitized', 'v1', 0, 1);
