INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4d008fc5-16d1-461c-b705-bab796302cfe', '06997ea1-0b4c-5451-8a58-b6e1d988662e', 'ඕසෝන් ස්ථරයේ ක්ෂය වීම සඳහා හයිඩ්‍රොෆ්ලුවොරොකාබන් (HFCs) දායක වේ.', 'ඕසෝන් ස්ථරයේ ක්ෂය වීම සඳහා හයිඩ්‍රොෆ්ලුවොරොකාබන් (HFCs) දායක වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('86ef766e-bf07-40aa-9fe7-bcf2e5d32cf3', '06997ea1-0b4c-5451-8a58-b6e1d988662e', 'පාරජම්බුල කිරණ ඇති විට ඕසෝන් ස්ථරයේ පවතින ඕසෝන් ස්වාභාවිකව වියෝජනයට භාජනය වේ.', 'පාරජම්බුල කිරණ ඇති විට ඕසෝන් ස්ථරයේ පවතින ඕසෝන් ස්වාභාවිකව වියෝජනයට භාජනය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('9f39cf95-3ca6-428c-96a4-970bb3332872', '06997ea1-0b4c-5451-8a58-b6e1d988662e', '$ClO^{\bullet}$ මුක්ත ඛණ්ඩක මගින් පමණක් ඕසෝන් ස්ථරයේ ක්ෂය වීම සිදු වේ.', '$ClO^{\bullet}$ මුක්ත ඛණ්ඩක මගින් පමණක් ඕසෝන් ස්ථරයේ ක්ෂය වීම සිදු වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('6effc025-ac08-5f31-a831-33fd64316ce1', '9dd2faee-abf5-56af-893b-8ac4c1c0af6c', 27, '<p>විද්‍යුත් විච්ඡේද්‍ය කෝෂයක් තුළ සිදු වන අර්ධ ප්‍රතික්‍රියාව සම්බන්ධයෙන් පහත සඳහන් කුමක් සත්‍ය වේ ද?<br>$$AlF_6^{3-}(aq) + 3e \rightarrow Al(s) + 6 F^-(aq)$$</p>', '<p>විද්‍යුත් විච්ඡේද්‍ය කෝෂයක් තුළ සිදු වන අර්ධ ප්‍රතික්‍රියාව සම්බන්ධයෙන් පහත සඳහන් කුමක් සත්‍ය වේ ද?<br>$$AlF_6^{3-}(aq) + 3e \rightarrow Al(s) + 6 F^-(aq)$$</p>', NULL, 'මෙම ප්‍රතික්‍රියාවේදී ඉලෙක්ට්‍රෝන (e) ග්‍රහණය කරගන්නා බැවින් එය ඔක්සිහරණ අර්ධ ප්‍රතික්‍රියාවකි. මෙහිදී $AlF_6^{3-}$ සංකීර්ණය තුළ +3 ඔක්සිකරණ අවස්ථාවේ පවතින Al පරමාණුව 0 අවස්ථාව දක්වා ඔක්සිහරණය වේ. එබැවින් $AlF_6^{3-}$ ඔක්සිහරණය වේ.', 'මෙම ප්‍රතික්‍රියාවේදී ඉලෙක්ට්‍රෝන (e) ග්‍රහණය කරගන්නා බැවින් එය ඔක්සිහරණ අර්ධ ප්‍රතික්‍රියාවකි. මෙහිදී $AlF_6^{3-}$ සංකීර්ණය තුළ +3 ඔක්සිකරණ අවස්ථාවේ පවතින Al පරමාණුව 0 අවස්ථාව දක්වා ඔක්සිහරණය වේ. එබැවින් $AlF_6^{3-}$ ඔක්සිහරණය වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
