INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('28a50086-13c7-5e65-8de6-17d253686b2c', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 4, '<p>The cause for the pain when stung by red ants is the formic acid which they apply on the sting. Application of which of the following on the sting is most effective to relieve the pain?</p>', '<p>The cause for the pain when stung by red ants is the formic acid which they apply on the sting. Application of which of the following on the sting is most effective to relieve the pain?</p>', NULL, 'Formic acid is a weak acid. To neutralize the acid and relieve the pain, a mild base should be applied. Lime water (calcium hydroxide solution) is basic, whereas vinegar is acidic and water/salt water are neutral.', 'Formic acid is a weak acid. To neutralize the acid and relieve the pain, a mild base should be applied. Lime water (calcium hydroxide solution) is basic, whereas vinegar is acidic and water/salt water are neutral.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
