INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('337895e2-5c94-5287-9b98-2e8511614d01', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 15, '<p>X, Y and Z are three successive elements in the periodic table and X is a noble gas. As which of the following species is Z most likely to exist in its compounds?</p>', '<p>X, Y and Z are three successive elements in the periodic table and X is a noble gas. As which of the following species is Z most likely to exist in its compounds?</p>', NULL, 'If X is a noble gas (Group 18), the next successive element Y must be an alkali metal (Group 1, forming $+1$ ions). The following element Z must be an alkaline earth metal (Group 2). Group 2 elements lose two electrons to achieve a stable noble gas configuration, forming $Z^{2+}$ ions.', 'If X is a noble gas (Group 18), the next successive element Y must be an alkali metal (Group 1, forming $+1$ ions). The following element Z must be an alkaline earth metal (Group 2). Group 2 elements lose two electrons to achieve a stable noble gas configuration, forming $Z^{2+}$ ions.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
