INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('34faea8d-a640-5225-8b7b-045146ddb56b', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 16, '<p>Four rules relating to electromagnetism and electromagnetic induction are given below.<br>A - Maxwell''s corkscrew rule<br>B - Right hand rule<br>C - Fleming''s left hand rule<br>D - Fleming''s right hand rule<br>Of these, the two rules that can be used to find the direction of the magnetic field around a conductor carrying an electric current are,</p>', '<p>Four rules relating to electromagnetism and electromagnetic induction are given below.<br>A - Maxwell''s corkscrew rule<br>B - Right hand rule<br>C - Fleming''s left hand rule<br>D - Fleming''s right hand rule<br>Of these, the two rules that can be used to find the direction of the magnetic field around a conductor carrying an electric current are,</p>', NULL, 'Maxwell''s corkscrew rule and the Right Hand Grip rule (B) are both used to determine the direction of the magnetic field lines circulating around a current-carrying straight conductor.', 'Maxwell''s corkscrew rule and the Right Hand Grip rule (B) are both used to determine the direction of the magnetic field lines circulating around a current-carrying straight conductor.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
