INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3e618dbf-ba8f-536c-aedb-720d5ba8964b', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 17, '<p>Consider the following statements.<br>A - An unbalanced force does not act on an object at rest freely suspended by a string.<br>B - An unbalanced force acts on an object moving with a uniform velocity.<br>C - The force exerted on the table by an object kept at rest on a horizontal table is equal to the force exerted by the table on the object in the opposite direction.<br>Of the above, the true statement/statements is/are,</p>', '<p>Consider the following statements.<br>A - An unbalanced force does not act on an object at rest freely suspended by a string.<br>B - An unbalanced force acts on an object moving with a uniform velocity.<br>C - The force exerted on the table by an object kept at rest on a horizontal table is equal to the force exerted by the table on the object in the opposite direction.<br>Of the above, the true statement/statements is/are,</p>', NULL, 'Statement A is true: an object at rest has a net force of zero (balanced forces). Statement B is false: an object moving at uniform velocity has zero acceleration, thus zero unbalanced force according to Newton''s first law. Statement C is true: this is an application of Newton''s third law of motion.', 'Statement A is true: an object at rest has a net force of zero (balanced forces). Statement B is false: an object moving at uniform velocity has zero acceleration, thus zero unbalanced force according to Newton''s first law. Statement C is true: this is an application of Newton''s third law of motion.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
