INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('7e4bda94-b91d-58a1-8e17-9d423b25a707', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 19, '<p>Of the following factors essential for photosynthesis, which factor cannot be tested in the school laboratory?</p>', '<p>Of the following factors essential for photosynthesis, which factor cannot be tested in the school laboratory?</p>', NULL, 'While we can easily deprive a plant part of light (using black paper), $CO_2$ (using KOH), or test variegated leaves for chlorophyll, we cannot safely deprive a living leaf entirely of water for a photosynthesis test without causing the plant tissue to wilt and die, preventing the experiment from being viable.', 'While we can easily deprive a plant part of light (using black paper), $CO_2$ (using KOH), or test variegated leaves for chlorophyll, we cannot safely deprive a living leaf entirely of water for a photosynthesis test without causing the plant tissue to wilt and die, preventing the experiment from being viable.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
