INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('e07c466f-bda4-5917-8a25-bd7f1af1a08d', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 20, '<p>The hydrocarbon with molecular formula $C_5H_{12}$,</p>', '<p>The hydrocarbon with molecular formula $C_5H_{12}$,</p>', NULL, '$C_5H_{12}$ fits the general formula for alkanes ($C_nH_{2n+2}$). The complete combustion equation is: $C_5H_{12} + 8O_2 \rightarrow 5CO_2 + 6H_2O$. Thus, 1 mole of pentane produces 6 moles of water.', '$C_5H_{12}$ fits the general formula for alkanes ($C_nH_{2n+2}$). The complete combustion equation is: $C_5H_{12} + 8O_2 \rightarrow 5CO_2 + 6H_2O$. Thus, 1 mole of pentane produces 6 moles of water.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
