INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5ab7f03f-a5ec-59d3-8225-392505152b3e', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 21, '<p>The main reason for the easy flow of electrons across the p-n junction of a forward biased diode is,</p>', '<p>The main reason for the easy flow of electrons across the p-n junction of a forward biased diode is,</p>', NULL, 'When a p-n junction is forward biased, the external voltage pushes majority charge carriers towards the junction. This significantly narrows the depletion region, which allows electrons to cross easily.', 'When a p-n junction is forward biased, the external voltage pushes majority charge carriers towards the junction. This significantly narrows the depletion region, which allows electrons to cross easily.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
