INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('536f6cdf-4fe3-5ab0-afa0-f1de02bc7024', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 22, '<p>There are two immiscible liquids A and B whose densities are $\\rho_A$ and $\\rho_B$ respectively. Three solid spheres X, Y and Z equal in radius and with densities $\\rho_X$, $\\rho_Y$ and $\\rho_Z$ respectively are in the liquids. X floats on A, Y floats at the interface of A and B, Z sinks in B. What is the correct statement about them?</p>
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('68309528-1b04-480a-9434-fba6664ff17d', '536f6cdf-4fe3-5ab0-afa0-f1de02bc7024', '$\rho_A < \rho_B$ and $\rho_X = \rho_Y < \rho_Z$', '$\rho_A < \rho_B$ and $\rho_X = \rho_Y < \rho_Z$', NULL, 'sanitized', 'v1', 0, 1);
