INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0ec0ff94-4967-4fea-90af-b5dd40787736', '536f6cdf-4fe3-5ab0-afa0-f1de02bc7024', '$\rho_A = \rho_X = \rho_Y$ and $\rho_B < \rho_Z$', '$\rho_A = \rho_X = \rho_Y$ and $\rho_B < \rho_Z$', NULL, 'sanitized', 'v1', 2, 0);
