INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('55a587f8-ec90-580e-bff2-90fe3c5f994e', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 23, '<p>u, v and w are three metals lying above hydrogen in the activity series. The method proposed by a group of students to compare their activity was taking a piece from each metal, reacting them with hydrochloric acid separately and comparing the volumes of hydrogen gas liberated within a fixed short period. Which of the following factors is not essential to be kept constant during the experiment?</p>', '<p>u, v and w are three metals lying above hydrogen in the activity series. The method proposed by a group of students to compare their activity was taking a piece from each metal, reacting them with hydrochloric acid separately and comparing the volumes of hydrogen gas liberated within a fixed short period. Which of the following factors is not essential to be kept constant during the experiment?</p>', NULL, 'To compare the reaction rates fairly, variables affecting the rate (surface area, temperature, acid concentration) must be controlled. The overall mass is not essential to keep constant as long as the surface area interacting with the acid is equal and there is excess acid.', 'To compare the reaction rates fairly, variables affecting the rate (surface area, temperature, acid concentration) must be controlled. The overall mass is not essential to keep constant as long as the surface area interacting with the acid is equal and there is excess acid.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html