INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4c37e3ee-abcf-5fba-ac95-8b6b10155b8f', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 25, '<p>Consider the following statements about amoeba.<br>A - Reproduction occurs by binary fission.<br>B - Binary fission occurs only by mitotic division.<br>Of the above statements,</p>', '<p>Consider the following statements about amoeba.<br>A - Reproduction occurs by binary fission.<br>B - Binary fission occurs only by mitotic division.<br>Of the above statements,</p>', NULL, 'Amoebas reproduce asexually through binary fission (Statement A is true). This process of cell division involves the exact replication of genetic material through mitosis before the cell splits (Statement B is true).', 'Amoebas reproduce asexually through binary fission (Statement A is true). This process of cell division involves the exact replication of genetic material through mitosis before the cell splits (Statement B is true).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
