INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('5013fe2f-be95-5bc9-9e4c-c1638cfc934a', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 26, '<p>Of P, Q, R and S, in which pair of resistor systems is the value of the equivalent resistance the same between X and Y?</p>', '<p>Of P, Q, R and S, in which pair of resistor systems is the value of the equivalent resistance the same between X and Y?</p>', NULL, 'Based on the marking scheme, the correct answer is option 2 (P and S). The equivalent resistance calculation aligns the systems denoted P and S to possess the exact same overall ohmic value across terminals X and Y.', 'Based on the marking scheme, the correct answer is option 2 (P and S). The equivalent resistance calculation aligns the systems denoted P and S to possess the exact same overall ohmic value across terminals X and Y.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
