INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('43ca0fa6-159e-513e-bd0d-293e02aac5c6', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 31, '<p>The magnetic train operated in Japan is lifted a bit up above the rails after it acquires an adequate speed and made to run forward. What is the main advantage obtained by this modern technological strategy?</p>', '<p>The magnetic train operated in Japan is lifted a bit up above the rails after it acquires an adequate speed and made to run forward. What is the main advantage obtained by this modern technological strategy?</p>', NULL, 'Maglev (magnetic levitation) trains float above the tracks. By eliminating physical contact between the train wheels and the rails, mechanical friction is almost completely reduced, allowing for extremely high speeds.', 'Maglev (magnetic levitation) trains float above the tracks. By eliminating physical contact between the train wheels and the rails, mechanical friction is almost completely reduced, allowing for extremely high speeds.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
