INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cddc5e7a-2329-504c-9c16-7453cabadaa0', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 33, '<p>In the form of a thin layer, metal X is applied on the iron sheet A and metal Y is applied on the iron sheet B. A small scratch was made at the centre of both sheets. Later, rusting has spread rapidly on A, but B has not been subjected to a considerable damage. The metals X and Y respectively can be,</p>', '<p>In the form of a thin layer, metal X is applied on the iron sheet A and metal Y is applied on the iron sheet B. A small scratch was made at the centre of both sheets. Later, rusting has spread rapidly on A, but B has not been subjected to a considerable damage. The metals X and Y respectively can be,</p>', NULL, 'If sheet A rusted rapidly after being scratched, metal X must be less reactive than Iron (like Tin - $Sn$). It provides cathodic protection, but accelerates rusting once scratched. If sheet B did not rust, metal Y must be more reactive than Iron (like Zinc - $Zn$), acting as a sacrificial anode.', 'If sheet A rusted rapidly after being scratched, metal X must be less reactive than Iron (like Tin - $Sn$). It provides cathodic protection, but accelerates rusting once scratched. If sheet B did not rust, metal Y must be more reactive than Iron (like Zinc - $Zn$), acting as a sacrificial anode.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
