INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1f42d4b0-3825-54b6-ba94-d6eb532f7c28', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 34, '<p>$600\text{ g}$ of water at temperature $80^\circ\text{C}$ were added to a vessel containing $200\text{ g}$ of water at $0^\circ\text{C}$. What is the final temperature of the mixture?<br>(specific heat capacity of water $= 4200\text{ J kg}^{-1} ^\circ\text{C}^{-1}$, assume that the vessel does not absorb heat.)</p>', '<p>$600\text{ g}$ of water at temperature $80^\circ\text{C}$ were added to a vessel containing $200\text{ g}$ of water at $0^\circ\text{C}$. What is the final temperature of the mixture?<br>(specific heat capacity of water $= 4200\text{ J kg}^{-1} ^\circ\text{C}^{-1}$, assume that the vessel does not absorb heat.)</p>', NULL, 'Using the principle of heat exchange: Heat lost by hot water = Heat gained by cold water.<br>$m_1 \times c \times \Delta T_1 = m_2 \times c \times \Delta T_2$<br>$600 \times (80 - T) = 200 \times (T - 0)$<br>$3(80 - T) = T$<br>$240 - 3T = T$<br>$4T = 240 \rightarrow T = 60^\circ\text{C}$.', 'Using the principle of heat exchange: Heat lost by hot water = Heat gained by cold water.<br>$m_1 \times c \times \Delta T_1 = m_2 \times c \times \Delta T_2$<br>$600 \times (80 - T) = 200 \times (T - 0)$<br>$3(80 - T) = T$<br>$240 - 3T = T$<br>$4T = 240 \rightarrow T = 60^\circ\text{C}$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
