INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('2c562670-19a2-5197-979e-03a033906f1e', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 35, '<p>The areas of cross section of the pistons of a hydraulic jack are $x\text{ m}^2$ and $4x\text{ m}^2$. How much is the force exerted on the larger piston when a force of $50\text{ N}$ is applied on the smaller piston?</p>', '<p>The areas of cross section of the pistons of a hydraulic jack are $x\text{ m}^2$ and $4x\text{ m}^2$. How much is the force exerted on the larger piston when a force of $50\text{ N}$ is applied on the smaller piston?</p>', NULL, 'According to Pascal''s Principle, pressure is transmitted equally in a confined fluid.<br>$\frac{F_1}{A_1} = \frac{F_2}{A_2}$<br>$\frac{50}{x} = \frac{F_2}{4x}$<br>$F_2 = 50 \times 4 = 200\text{ N}$.', 'According to Pascal''s Principle, pressure is transmitted equally in a confined fluid.<br>$\frac{F_1}{A_1} = \frac{F_2}{A_2}$<br>$\frac{50}{x} = \frac{F_2}{4x}$<br>$F_2 = 50 \times 4 = 200\text{ N}$.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
