INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('cf4e6598-08e1-5c1a-8a1c-e16d4ab456e1', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 38, '<p>In which phase of the growth curve of population does the number of organisms in the population reach its carrying capacity?</p>', '<p>In which phase of the growth curve of population does the number of organisms in the population reach its carrying capacity?</p>', NULL, 'A standard population growth curve has 4 phases: 1) Lag phase, 2) Log/Exponential phase, 3) Deceleration phase, and 4) Stationary phase. The carrying capacity (maximum stable population size) is reached and maintained during the fourth phase (stationary phase).', 'A standard population growth curve has 4 phases: 1) Lag phase, 2) Log/Exponential phase, 3) Deceleration phase, and 4) Stationary phase. The carrying capacity (maximum stable population size) is reached and maintained during the fourth phase (stationary phase).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
