INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('79c5210d-a650-58e0-85c7-72e9503eaeda', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 39, '<p>Which of the following statements is true about the ecological pyramids?</p>', '<p>Which of the following statements is true about the ecological pyramids?</p>', NULL, 'Through the process of biomagnification, non-biodegradable toxins and heavy metals progressively accumulate in concentration as they move up the food chain, reaching their highest concentration in apex predators (the highest trophic level).', 'Through the process of biomagnification, non-biodegradable toxins and heavy metals progressively accumulate in concentration as they move up the food chain, reaching their highest concentration in apex predators (the highest trophic level).', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e45e22aa-a8ef-46e2-8505-126962c7774e', '79c5210d-a650-58e0-85c7-72e9503eaeda', 'Number pyramids are always upright.', 'Number pyramids are always upright.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('14a4962a-9cfb-486a-85c9-09de92c6165d', '79c5210d-a650-58e0-85c7-72e9503eaeda', 'In a biomass pyramid, omnivores can exist only as secondary consumers.', 'In a biomass pyramid, omnivores can exist only as secondary consumers.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6c4d8ec7-e27b-421d-86ce-8215b18bcc3f', '79c5210d-a650-58e0-85c7-72e9503eaeda', 'Heavy metals accumulate most in the highest level of a biomass pyramid.', 'Heavy metals accumulate most in the highest level of a biomass pyramid.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0ab882eb-05f7-4da0-8ae0-6e32b75ead09', '79c5210d-a650-58e0-85c7-72e9503eaeda', 'Biomagnification is the incorporation of a higher amount of energy in the higher trophic levels of an energy pyramid.', 'Biomagnification is the incorporation of a higher amount of energy in the higher trophic levels of an energy pyramid.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c252e973-d4c3-5154-b6fa-adca870bc90e', 'a3afcd83-658e-5a94-81d2-d8ffa2eedbbc', 40, '<p>As a student says, nitrogenous nutrients in a soil decrease after a flood due to following reasons.<br>A - occurrence of denitrification<br>B - percolation deeper into soil (leaching)<br>C - getting washed away from the surface soil<br>D - decomposition of organic matter<br>Of these only,</p>', '<p>As a student says, nitrogenous nutrients in a soil decrease after a flood due to following reasons.<br>A - occurrence of denitrification<br>B - percolation deeper into soil (leaching)<br>C - getting washed away from the surface soil<br>D - decomposition of organic matter<br>Of these only,</p>', NULL, 'Flooding causes waterlogged, anaerobic soil conditions which promote denitrification (A). Water also physically washes away surface nutrients (C) and leaches soluble nitrates deeper into the soil out of root reach (B). Decomposition of organic matter (D) would actually *add* nutrients, so it is not a reason for the decrease.', 'Flooding causes waterlogged, anaerobic soil conditions which promote denitrification (A). Water also physically washes away surface nutrients (C) and leaches soluble nitrates deeper into the soil out of root reach (B). Decomposition of organic matter (D) would actually *add* nutrients, so it is not a reason for the decrease.', NULL, 'sanitized', 'v1', 4, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
