INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('1d8f4487-23cc-5e7e-b963-93ef8c2392e7', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 1, '<p>සජීවීන් තුළ අංශු මාත්‍ර මූලද්‍රව්‍යවල ප්‍රධාන කාර්යභාරය වන්නේ</p>', '<p>සජීවීන් තුළ අංශු මාත්‍ර මූලද්‍රව්‍යවල ප්‍රධාන කාර්යභාරය වන්නේ</p>', NULL, 'අංශු මාත්‍ර මූලද්‍රව්‍ය (Trace elements) බොහෝ විට එන්සයිමවල ක්‍රියාකාරිත්වයට අත්‍යවශ්‍ය සහසාධක (cofactors) ලෙස ක්‍රියා කරයි (උදා: $Zn^{2+}$, $Cu^{2+}$).', 'අංශු මාත්‍ර මූලද්‍රව්‍ය (Trace elements) බොහෝ විට එන්සයිමවල ක්‍රියාකාරිත්වයට අත්‍යවශ්‍ය සහසාධක (cofactors) ලෙස ක්‍රියා කරයි (උදා: $Zn^{2+}$, $Cu^{2+}$).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
