INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('67f19a3a-58b5-4bdd-a282-a13411a3c03b', '1d8f4487-23cc-5e7e-b963-93ef8c2392e7', 'පරිවෘත්තියේදී ප්‍රතික්‍රියක ලෙස ක්‍රියා කිරීම ය.', 'පරිවෘත්තියේදී ප්‍රතික්‍රියක ලෙස ක්‍රියා කිරීම ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c0d65620-51de-5b25-8d42-16d977d001e0', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 2, '<p>සුන්‍යෂ්ටික සෛල තුළ න්‍යෂ්ටියට අමතර ව DNA තිබෙනුයේ</p>', '<p>සුන්‍යෂ්ටික සෛල තුළ න්‍යෂ්ටියට අමතර ව DNA තිබෙනුයේ</p>', NULL, 'සුන්‍යෂ්ටික සෛලවල ප්‍රධාන ජානමය ද්‍රව්‍යය න්‍යෂ්ටිය තුළ පවතින අතර, මයිටොකොන්ඩ්‍රියා සහ හරිතලව යන ඉන්ද්‍රයිකා තුළ ද ඒවාටම ආවේණික වූ චක්‍රීය DNA අඩංගු වේ.', 'සුන්‍යෂ්ටික සෛලවල ප්‍රධාන ජානමය ද්‍රව්‍යය න්‍යෂ්ටිය තුළ පවතින අතර, මයිටොකොන්ඩ්‍රියා සහ හරිතලව යන ඉන්ද්‍රයිකා තුළ ද ඒවාටම ආවේණික වූ චක්‍රීය DNA අඩංගු වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('97d8ea32-9bae-456c-9c8e-53082ffdcd52', 'c0d65620-51de-5b25-8d42-16d977d001e0', 'රයිබොසෝම සහ කේන්ද්‍රිකා තුළ ය.', 'රයිබොසෝම සහ කේන්ද්‍රිකා තුළ ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('cee39818-3589-4e3f-9bc4-dc859882d52b', 'c0d65620-51de-5b25-8d42-16d977d001e0', 'මයිටොකොන්ඩ්‍රියා සහ හරිතලව තුළ ය.', 'මයිටොකොන්ඩ්‍රියා සහ හරිතලව තුළ ය.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('53008b3a-ee8f-4e4b-b18e-fed61d26a0d0', 'c0d65620-51de-5b25-8d42-16d977d001e0', 'න්‍යෂ්ටිකාව සහ පෙරොක්සිසෝම තුළ ය.', 'න්‍යෂ්ටිකාව සහ පෙරොක්සිසෝම තුළ ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('01c06862-6375-40aa-9381-9774459503ac', 'c0d65620-51de-5b25-8d42-16d977d001e0', 'ක්ෂුද්‍ර දේහ සහ ගොල්ගි දේහ තුළ ය.', 'ක්ෂුද්‍ර දේහ සහ ගොල්ගි දේහ තුළ ය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3d8273dc-351f-44e0-a94e-bd8d044a4b2b', 'c0d65620-51de-5b25-8d42-16d977d001e0', 'ග්ලයොක්සිසෝම සහ අන්තඃප්ලාස්මීය ජාලිකාව තුළ ය.', 'ග්ලයොක්සිසෝම සහ අන්තඃප්ලාස්මීය ජාලිකාව තුළ ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8b90e372-f486-522c-87cf-47c24508e0ee', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 3, '<p>පහත සඳහන් ඒවා අතුරෙන් අපිච්ඡද පටකවල කෘත්‍යයක් නොවන්නේ කුමක්ද?</p>', '<p>පහත සඳහන් ඒවා අතුරෙන් අපිච්ඡද පටකවල කෘත්‍යයක් නොවන්නේ කුමක්ද?</p>', NULL, 'අපිච්ඡද පටක මගින් ආරක්ෂාව, ස්‍රාවය, සහ අවශෝෂණය වැනි කාර්යයන් ඉටු කරයි. පරිවහනය (Transport) ප්‍රධාන වශයෙන් රුධිරය වැනි සම්බන්ධක පටක හෝ සනාල පටක මගින් සිදු වේ. මෙහිදී නිල පිළිතුරු පත්‍රයට අනුව වඩාත් නිවැරදි නොවන කෘත්‍යය ලෙස පරිවහනය (2) දක්වා ඇත.', 'අපිච්ඡද පටක මගින් ආරක්ෂාව, ස්‍රාවය, සහ අවශෝෂණය වැනි කාර්යයන් ඉටු කරයි. පරිවහනය (Transport) ප්‍රධාන වශයෙන් රුධිරය වැනි සම්බන්ධක පටක හෝ සනාල පටක මගින් සිදු වේ. මෙහිදී නිල පිළිතුරු පත්‍රයට අනුව වඩාත් නිවැරදි නොවන කෘත්‍යය ලෙස පරිවහනය (2) දක්වා ඇත.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
