INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4e770dad-ad64-42e0-8a11-bfeb4c012bba', '8b9af292-131a-5d40-b220-5debacebb752', 'ප්ලෝයම පරිවහනය නිෂ්ක්‍රිය ක්‍රියාවලියකි.', 'ප්ලෝයම පරිවහනය නිෂ්ක්‍රිය ක්‍රියාවලියකි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e68ecc30-6cc7-44f0-b5d2-b250f9dcc5a5', '8b9af292-131a-5d40-b220-5debacebb752', 'ප්ලෝයම බැර කිරීම නිසා පෙනේර නළය තුළ ජල විභවය වැඩි වේ.', 'ප්ලෝයම බැර කිරීම නිසා පෙනේර නළය තුළ ජල විභවය වැඩි වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('64cf0e16-ffbd-50a2-bd5c-4e168c68402d', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 16, '<p>මිනිස් රුධිර සෛල පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>මිනිස් රුධිර සෛල පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'විශාල පරපෝෂිත පණුවන් වැනි රුධිර පරපෝෂිතයන් විනාශ කිරීම සහ ඉවත් කිරීම සඳහා ඉයොසිනොෆිල (Eosinophils) ප්‍රධාන වශයෙන් දායක වේ.', 'විශාල පරපෝෂිත පණුවන් වැනි රුධිර පරපෝෂිතයන් විනාශ කිරීම සහ ඉවත් කිරීම සඳහා ඉයොසිනොෆිල (Eosinophils) ප්‍රධාන වශයෙන් දායක වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('2ac8e77d-f80c-42c2-9718-54200af43891', '64cf0e16-ffbd-50a2-bd5c-4e168c68402d', 'සියලු රුධිර සෛලවලින් 90%ක් පමණ වන්නේ රක්තාණුයි.', 'සියලු රුධිර සෛලවලින් 90%ක් පමණ වන්නේ රක්තාණුයි.', NULL, 'sanitized', 'v1', 0, 1);
