INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('52c70bc7-2eae-4a40-9fe5-acf2a526124e', '64cf0e16-ffbd-50a2-bd5c-4e168c68402d', 'රුධිර පරපෝෂිතයන් ඉවත් කිරීමට ඉයොසිනොෆිල දායක වේ.', 'රුධිර පරපෝෂිතයන් ඉවත් කිරීමට ඉයොසිනොෆිල දායක වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c3815f95-a3f8-41a8-a565-2e8d2d0de5b0', '64cf0e16-ffbd-50a2-bd5c-4e168c68402d', 'නිරෝගී වැඩිහිටි සාමාන්‍ය පුද්ගලයකුගේ වසා සෛල සංඛ්‍යාව රුධිරය ලීටරයකට $1.5\times10^{6}$ සිට $3.5\times10^{6}$ දක්වා වේ.', 'නිරෝගී වැඩිහිටි සාමාන්‍ය පුද්ගලයකුගේ වසා සෛල සංඛ්‍යාව රුධිරය ලීටරයකට $1.5\times10^{6}$ සිට $3.5\times10^{6}$ දක්වා වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('c505168c-cfff-535f-aaab-cd99d474b87c', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 17, '<p>සත්ත්වයින්ගේ රුධිර සංසරණ පද්ධති පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>සත්ත්වයින්ගේ රුධිර සංසරණ පද්ධති පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'ඇනලීඩාවන්ට (Annelida - උදා: ගැඩවිලා) සහ මත්ස්‍යයන්ට සංවෘත රුධිර සංසරණ පද්ධති (Closed circulatory systems) පිහිටා ඇත. කෘමීන්ට විවෘත පද්ධතියක් ඇති අතර පටි පණුවන්ට සංසරණ පද්ධතියක් නොමැත. මිනිස් හෘදයේ ප්‍රධාන ගතිකරය (Pacemaker) වන්නේ SA ගැටයයි.', 'ඇනලීඩාවන්ට (Annelida - උදා: ගැඩවිලා) සහ මත්ස්‍යයන්ට සංවෘත රුධිර සංසරණ පද්ධති (Closed circulatory systems) පිහිටා ඇත. කෘමීන්ට විවෘත පද්ධතියක් ඇති අතර පටි පණුවන්ට සංසරණ පද්ධතියක් නොමැත. මිනිස් හෘදයේ ප්‍රධාන ගතිකරය (Pacemaker) වන්නේ SA ගැටයයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
