INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('86a07ab1-254b-4e32-a889-f135a406734e', 'c505168c-cfff-535f-aaab-cd99d474b87c', 'ක්ලෝරොක්රුවෝරින් ක්‍රස්ටේශියාවන්ගේ ශ්වසන වර්ණකයක් ලෙස ක්‍රියා කරයි.', 'ක්ලෝරොක්රුවෝරින් ක්‍රස්ටේශියාවන්ගේ ශ්වසන වර්ණකයක් ලෙස ක්‍රියා කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('fc18288c-7aa6-4148-8c2e-3e7f0743ca51', 'c505168c-cfff-535f-aaab-cd99d474b87c', 'කර්ණික - කෝෂික (AV) ගැටය මිනිස් හෘදයේ ගතිකරය ලෙස ක්‍රියා කරයි.', 'කර්ණික - කෝෂික (AV) ගැටය මිනිස් හෘදයේ ගතිකරය ලෙස ක්‍රියා කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ce5719dd-fdd3-580f-a626-8918fb4c4f03', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 18, '<p>මිනිස් මොළය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', '<p>මිනිස් මොළය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් නිවැරදි වන්නේ කුමක්ද?</p>', NULL, 'මස්තිෂ්කය (Cerebrum), විශේෂයෙන්ම එහි ඇති පාරියටික ඛණ්ඩිකාව, වේදනාව වැනි දේහ සංවේදන සංජානනය කිරීම (Perception of sensory inputs) සඳහා වැදගත් වේ. කිවිසීම සහ කැස්ස පාලනය කරන්නේ සුෂුම්නා ශීර්ෂකය මගිනි.', 'මස්තිෂ්කය (Cerebrum), විශේෂයෙන්ම එහි ඇති පාරියටික ඛණ්ඩිකාව, වේදනාව වැනි දේහ සංවේදන සංජානනය කිරීම (Perception of sensory inputs) සඳහා වැදගත් වේ. කිවිසීම සහ කැස්ස පාලනය කරන්නේ සුෂුම්නා ශීර්ෂකය මගිනි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ca192ee9-e1b9-4005-a313-10d9ccf14705', 'ce5719dd-fdd3-580f-a626-8918fb4c4f03', 'සිව්බිඩි දේහ ව්‍යුත්පන්න වී ඇත්තේ කලල අපර මස්තිෂ්කයෙනි.', 'සිව්බිඩි දේහ ව්‍යුත්පන්න වී ඇත්තේ කලල අපර මස්තිෂ්කයෙනි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('020599c4-3d8e-4945-a834-1d09c36085d4', 'ce5719dd-fdd3-580f-a626-8918fb4c4f03', 'වැරෝලි සේතුව, හුස්ම ගැනීමේ ශීඝ්‍රතාව යාමනය කරයි.', 'වැරෝලි සේතුව, හුස්ම ගැනීමේ ශීඝ්‍රතාව යාමනය කරයි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('e1570b16-2148-4cd4-9eef-d56108095f05', 'ce5719dd-fdd3-580f-a626-8918fb4c4f03', 'පූර්ව මස්තිෂ්කය, අක්ෂි පේශිවල ප්‍රතීක චලන පාලනය කරයි.', 'පූර්ව මස්තිෂ්කය, අක්ෂි පේශිවල ප්‍රතීක චලන පාලනය කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('1e39a358-b49f-4e6d-af97-52c88be0c95c', 'ce5719dd-fdd3-580f-a626-8918fb4c4f03', 'අනුමස්තිෂ්කය, කිවිසීම සහ කැස්ස පාලනය කරයි.', 'අනුමස්තිෂ්කය, කිවිසීම සහ කැස්ස පාලනය කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('84664ae2-a28f-490a-a9ce-3a020ec8c268', 'ce5719dd-fdd3-580f-a626-8918fb4c4f03', 'මස්තිෂ්කය, වේදනා සංවේදක සංජානනය සඳහා සහභාගි වේ.', 'මස්තිෂ්කය, වේදනා සංවේදක සංජානනය සඳහා සහභාගි වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('8d0992c6-68ec-58f8-af47-33ba326fafba', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 19, '<p>නියුරෝනවල කායික විද්‍යාව පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>නියුරෝනවල කායික විද්‍යාව පිළිබඳ වැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'ක්‍රියා විභවයේ ප්‍රතිධ්‍රැවණ (Repolarization) කලාවේදී සිදුවන්නේ $K^{+}$ අයන සෛලයෙන් පිටතට ගැලීමයි (efflux), ඇතුළට ගැලීමක් නොවේ.', 'ක්‍රියා විභවයේ ප්‍රතිධ්‍රැවණ (Repolarization) කලාවේදී සිදුවන්නේ $K^{+}$ අයන සෛලයෙන් පිටතට ගැලීමයි (efflux), ඇතුළට ගැලීමක් නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('914962e4-d300-43bf-b5f5-a3168c379c87', '8d0992c6-68ec-58f8-af47-33ba326fafba', 'අක්‍රිය පටල විභවය පවත්වා ගැනීම සඳහා සෝඩියම් - පොටෑසියම් පොම්පය අත්‍යවශ්‍ය ය.', 'අක්‍රිය පටල විභවය පවත්වා ගැනීම සඳහා සෝඩියම් - පොටෑසියම් පොම්පය අත්‍යවශ්‍ය ය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('0f16ad3c-cd61-4d35-9cc3-28339dd8e490', '8d0992c6-68ec-58f8-af47-33ba326fafba', 'අක්‍රිය පටල විභවය - 70 mV පමණ වේ.', 'අක්‍රිය පටල විභවය - 70 mV පමණ වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('a566b50e-1d73-41ac-b541-32615ea57317', '8d0992c6-68ec-58f8-af47-33ba326fafba', 'ක්‍රියා විභවයක් පවතින කාලය 2 ms පමණ වේ.', 'ක්‍රියා විභවයක් පවතින කාලය 2 ms පමණ වේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f68cff1d-1827-410f-a26a-37193ab38b45', '8d0992c6-68ec-58f8-af47-33ba326fafba', 'මයලිනීභූත අක්සනයක ක්‍රියා විභවය ඇති වන්නේ රැන්වියර් ගැටවල පමණි.', 'මයලිනීභූත අක්සනයක ක්‍රියා විභවය ඇති වන්නේ රැන්වියර් ගැටවල පමණි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5e78a2c8-dd5a-4afb-be19-475d2e90209d', '8d0992c6-68ec-58f8-af47-33ba326fafba', 'ක්‍රියා විභවයේ ප්‍රතිධ්‍රැවණ කලාවේදී $K^{+}$ ඇතුළට ගැලීම සිදු වේ.', 'ක්‍රියා විභවයේ ප්‍රතිධ්‍රැවණ කලාවේදී $K^{+}$ ඇතුළට ගැලීම සිදු වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('92a09568-bd94-52ba-a040-70a512cc21cb', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 20, '<p>මිනිස් කැල්සිටෝනින් හෝර්මෝනය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් වැරදි වන්නේ කුමක්ද?</p>', '<p>මිනිස් කැල්සිටෝනින් හෝර්මෝනය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් වැරදි වන්නේ කුමක්ද?</p>', NULL, 'කැල්සිටෝනින් හෝර්මෝනය ස්‍රාවය කරනු ලබන්නේ තයිරොයිඩ් ග්‍රන්ථියේ පරාස්‍යුනිකා සෛල (Parafollicular cells / C cells) මගිනි. ස්‍යුනිකා සෛල (Follicular cells) මගින් ස්‍රාවය කරන්නේ තයිරොක්සීන් ය.', 'කැල්සිටෝනින් හෝර්මෝනය ස්‍රාවය කරනු ලබන්නේ තයිරොයිඩ් ග්‍රන්ථියේ පරාස්‍යුනිකා සෛල (Parafollicular cells / C cells) මගිනි. ස්‍යුනිකා සෛල (Follicular cells) මගින් ස්‍රාවය කරන්නේ තයිරොක්සීන් ය.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
