INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('d7c81a05-d9f9-402b-ba54-a28ee6a99667', '92a09568-bd94-52ba-a040-70a512cc21cb', 'එය රුධිර කැල්සියම් මට්ටම අඩු කරයි.', 'එය රුධිර කැල්සියම් මට්ටම අඩු කරයි.', NULL, 'sanitized', 'v1', 1, 0);
