INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('59e3a239-68e5-4384-84f0-118e3d0393dd', '92a09568-bd94-52ba-a040-70a512cc21cb', 'එය වෘක්කාණුව තුළදී කැල්සියම් ප්‍රතිශෝෂණය කිරීම නිෂේධනය කරයි.', 'එය වෘක්කාණුව තුළදී කැල්සියම් ප්‍රතිශෝෂණය කිරීම නිෂේධනය කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('be0dce63-601b-4871-8858-525e8a49ce7c', '92a09568-bd94-52ba-a040-70a512cc21cb', 'එහි බලපෑම් පැරාතයිරොයිඩ හෝර්මෝනයේ බලපෑම්වලට ප්‍රතිවිරුද්ධය.', 'එහි බලපෑම් පැරාතයිරොයිඩ හෝර්මෝනයේ බලපෑම්වලට ප්‍රතිවිරුද්ධය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('d758c933-052d-58e8-935a-412e148521bf', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 21, '<p>මිනිස් හෝර්මෝන පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මිනිස් හෝර්මෝන පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'ADH (ප්‍රතිමූත්‍රික හෝර්මෝනය) මගින් වෘක්කාණුවේ විදුර සංවලිත නාලිකාවේ සහ සංග්‍රාහක ප්‍රණාලයේ ජල පාරගම්‍යතාව වැඩි කර ජලය ප්‍රතිශෝෂණය කිරීම උත්තේජනය කරයි.', 'ADH (ප්‍රතිමූත්‍රික හෝර්මෝනය) මගින් වෘක්කාණුවේ විදුර සංවලිත නාලිකාවේ සහ සංග්‍රාහක ප්‍රණාලයේ ජල පාරගම්‍යතාව වැඩි කර ජලය ප්‍රතිශෝෂණය කිරීම උත්තේජනය කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8ce56466-1c10-4ad2-ae0f-6742d2923e3d', 'd758c933-052d-58e8-935a-412e148521bf', 'කොලිසිස්ටොකයිනින්, අග්න්‍යාශය සහ අක්මාව යන දෙක ම මත ක්‍රියා කරයි.', 'කොලිසිස්ටොකයිනින්, අග්න්‍යාශය සහ අක්මාව යන දෙක ම මත ක්‍රියා කරයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f0bc85ec-3b31-4f5d-86d3-cfbd6a23ecb5', 'd758c933-052d-58e8-935a-412e148521bf', 'B වසා සෛලවල විකසනය කෙරෙහි තයිමස බලපායි.', 'B වසා සෛලවල විකසනය කෙරෙහි තයිමස බලපායි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('778d9bee-bd29-4892-ba8b-65a377a0fed8', 'd758c933-052d-58e8-935a-412e148521bf', 'ග්ලූකගන් ස්‍රාවය කරනු ලබන්නේ ලැන්ගර්හැන් දීපිකාවල ß සෛල මගිනි.', 'ග්ලූකගන් ස්‍රාවය කරනු ලබන්නේ ලැන්ගර්හැන් දීපිකාවල ß සෛල මගිනි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('709b8d6b-d80c-46ac-9ab0-d70b076ef0b8', 'd758c933-052d-58e8-935a-412e148521bf', 'වෘක්කාණුවේදී $Na^{+}$ සහ $K^{+}$ ප්‍රතිශෝෂණය වීම ඇල්ඩොස්ටෙරොන් මගින් උත්තේජනය වේ.', 'වෘක්කාණුවේදී $Na^{+}$ සහ $K^{+}$ ප්‍රතිශෝෂණය වීම ඇල්ඩොස්ටෙරොන් මගින් උත්තේජනය වේ.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('90bfec4f-0833-49f8-b0e6-4678337fe934', 'd758c933-052d-58e8-935a-412e148521bf', 'වෘක්ක නාලිකාවල විදුර සංවලිත නාලිකාව සහ සංග්‍රාහක ප්‍රණාලය මත ADH ක්‍රියා කරයි.', 'වෘක්ක නාලිකාවල විදුර සංවලිත නාලිකාව සහ සංග්‍රාහක ප්‍රණාලය මත ADH ක්‍රියා කරයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('ea05aff7-f62f-5a78-a6b3-8c45527b0959', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 22, '<p>බහිස්ස්‍රාවය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් වැරදි වන්නේ කුමක්ද?</p>', '<p>බහිස්ස්‍රාවය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් වැරදි වන්නේ කුමක්ද?</p>', NULL, 'බහිස්ස්‍රාවය (Excretion) යනු දේහයේ පරිවෘත්තීය ප්‍රතික්‍රියාවලින් හටගන්නා අපද්‍රව්‍ය බැහැර කිරීමයි. එය නයිට්‍රජනීය අපද්‍රව්‍ය ඉවත් කිරීමට පමණක් සීමා නොවේ (උදා: කාබන්ඩයොක්සයිඩ් බැහැර කිරීම ද බහිස්ස්‍රාවයකි).', 'බහිස්ස්‍රාවය (Excretion) යනු දේහයේ පරිවෘත්තීය ප්‍රතික්‍රියාවලින් හටගන්නා අපද්‍රව්‍ය බැහැර කිරීමයි. එය නයිට්‍රජනීය අපද්‍රව්‍ය ඉවත් කිරීමට පමණක් සීමා නොවේ (උදා: කාබන්ඩයොක්සයිඩ් බැහැර කිරීම ද බහිස්ස්‍රාවයකි).', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
