INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('f7bc8974-58ac-4dff-a724-646f46b1fa7b', 'ea05aff7-f62f-5a78-a6b3-8c45527b0959', 'මිනිසුන්ගේ පිත්ත වර්ණක, වෘක්ක සහ ආහාර මාර්ගය මගින් බහිස්ස්‍රාවය කෙරේ.', 'මිනිසුන්ගේ පිත්ත වර්ණක, වෘක්ක සහ ආහාර මාර්ගය මගින් බහිස්ස්‍රාවය කෙරේ.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3b295f9a-27bd-440e-b89c-2982d296b094', 'ea05aff7-f62f-5a78-a6b3-8c45527b0959', 'වෘක්කිකා, ඇනලීඩාවන්ගේ සහ මොලස්කාවන්ගේ බහිස්ස්‍රාවී ව්‍යුහ යි.', 'වෘක්කිකා, ඇනලීඩාවන්ගේ සහ මොලස්කාවන්ගේ බහිස්ස්‍රාවී ව්‍යුහ යි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5abec3cc-7d3c-4cbc-9dcc-0d94aee2da18', 'ea05aff7-f62f-5a78-a6b3-8c45527b0959', 'ක්ෂීරපායීන්ගේ නයිට්‍රජනීය බහිස්ස්‍රාවයේ ප්‍රථම ඵලය ඇමෝනියාය.', 'ක්ෂීරපායීන්ගේ නයිට්‍රජනීය බහිස්ස්‍රාවයේ ප්‍රථම ඵලය ඇමෝනියාය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('3d77c867-4cd3-5cc3-b104-ebb9108bae71', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 23, '<p>මිනිස් කශේරුකා පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>මිනිස් කශේරුකා පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'දෙවන ග්‍රීව කශේරුකාව වන අක්ෂ කශේරුකාවේ (Axis vertebra) දේහයෙන් ඉහළට විහිදුණු දන්තයක හැඩය ඇති උත්තර ප්‍රසරයක් (odontoid process / dens) පිහිටයි.', 'දෙවන ග්‍රීව කශේරුකාව වන අක්ෂ කශේරුකාවේ (Axis vertebra) දේහයෙන් ඉහළට විහිදුණු දන්තයක හැඩය ඇති උත්තර ප්‍රසරයක් (odontoid process / dens) පිහිටයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
