INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8b79aab2-4447-450f-b554-91e23b13b8dd', '3d77c867-4cd3-5cc3-b104-ebb9108bae71', 'උරස් කශේරුකාවේ ද්විභින්න කණ්ටක ප්‍රසරයක් ඇත.', 'උරස් කශේරුකාවේ ද්විභින්න කණ්ටක ප්‍රසරයක් ඇත.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4725e75e-6cc2-4503-99c1-6edc455008ea', '3d77c867-4cd3-5cc3-b104-ebb9108bae71', 'විශාලම කශේරුකා ඡිද්‍රය ඇත්තේ කටී කශේරුකාවල ය.', 'විශාලම කශේරුකා ඡිද්‍රය ඇත්තේ කටී කශේරුකාවල ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('76d78a52-efde-56aa-9d3d-726f08a90d0b', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 24, '<p>ඔසප් චක්‍රය පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', '<p>ඔසප් චක්‍රය පිළිබඳ නිවැරදි ප්‍රකාශය තෝරන්න.</p>', NULL, 'කෝපස් ලුටියමය විනාශ වී යාම නිසා රුධිරයේ ඊස්ට්‍රජන් සහ ප්‍රොජෙස්ටරෝන් හෝර්මෝන මට්ටම්වල ඇතිවන සීඝ්‍ර පහළ යාම ගර්භාෂ අභ්‍යන්තර ආස්තරය ගැලවී යාමට (ඔසප් වීමට) හේතු වේ.', 'කෝපස් ලුටියමය විනාශ වී යාම නිසා රුධිරයේ ඊස්ට්‍රජන් සහ ප්‍රොජෙස්ටරෝන් හෝර්මෝන මට්ටම්වල ඇතිවන සීඝ්‍ර පහළ යාම ගර්භාෂ අභ්‍යන්තර ආස්තරය ගැලවී යාමට (ඔසප් වීමට) හේතු වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('3c2efb82-dcb4-4e9d-92ea-22413a2bf523', '76d78a52-efde-56aa-9d3d-726f08a90d0b', 'චක්‍රයේදී ප්‍රොජෙස්ටරෝන් මට්ටම උච්ච වනුයේ ඔසප් වීමට දින 2-3 කට පෙරය.', 'චක්‍රයේදී ප්‍රොජෙස්ටරෝන් මට්ටම උච්ච වනුයේ ඔසප් වීමට දින 2-3 කට පෙරය.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('54cd79b2-58d1-4cae-84d0-213a5abcf67f', '76d78a52-efde-56aa-9d3d-726f08a90d0b', 'එය ආරම්භ කෙරෙනුයේ පිටියුටරි හෝර්මෝන මගිනි.', 'එය ආරම්භ කෙරෙනුයේ පිටියුටරි හෝර්මෝන මගිනි.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c0a9e4a1-8fc7-4548-83d9-98aedfaa8ae1', '76d78a52-efde-56aa-9d3d-726f08a90d0b', 'චක්‍රයේදී උච්ච FSH මට්ටම, උච්ච LH මට්ටමට වඩා වැඩි ය.', 'චක්‍රයේදී උච්ච FSH මට්ටම, උච්ච LH මට්ටමට වඩා වැඩි ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c3c07e7f-1603-4f4a-9e97-6e8546ea7327', '76d78a52-efde-56aa-9d3d-726f08a90d0b', 'ප්‍රගුණන අවධිය සහ ස්‍රාවී අවධිය එකම දිගින් යුක්තය.', 'ප්‍රගුණන අවධිය සහ ස්‍රාවී අවධිය එකම දිගින් යුක්තය.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('bc9f75a1-8654-4ab1-bba1-5514601e5274', '76d78a52-efde-56aa-9d3d-726f08a90d0b', 'ඊස්ට්‍රජන් සහ ප්‍රොජෙස්ටරෝන් මට්ටම්වල අනවරත අඩු වීම නිසා ඔසප් වීම සිදු වේ.', 'ඊස්ට්‍රජන් සහ ප්‍රොජෙස්ටරෝන් මට්ටම්වල අනවරත අඩු වීම නිසා ඔසප් වීම සිදු වේ.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('4ae9a879-e58e-5643-ae4c-7db9aa08539b', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 25, '<p>මානව පැලෝපීය නාලය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් වැරදි වන්නේ කුමක්ද?</p>', '<p>මානව පැලෝපීය නාලය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් වැරදි වන්නේ කුමක්ද?</p>', NULL, 'ඩිම්බයක් සහ ශුක්‍රාණුවක් සාමාන්‍යයෙන් සංසේචනය වන්නේ පැලෝපීය නාලයේ ඉහළ පුළුල් වූ කොටසේ (ampulla) දී මිස එහි පහළ $\frac{1}{3}$ ප්‍රදේශයේදී නොවේ.', 'ඩිම්බයක් සහ ශුක්‍රාණුවක් සාමාන්‍යයෙන් සංසේචනය වන්නේ පැලෝපීය නාලයේ ඉහළ පුළුල් වූ කොටසේ (ampulla) දී මිස එහි පහළ $\frac{1}{3}$ ප්‍රදේශයේදී නොවේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('23ec9840-18fb-4370-a38e-c6def5f029a0', '4ae9a879-e58e-5643-ae4c-7db9aa08539b', 'එය විදුර කෙළවරේ පුනීලයක් වැනි විවරයක් සහිත ප්‍රණාලයකි.', 'එය විදුර කෙළවරේ පුනීලයක් වැනි විවරයක් සහිත ප්‍රණාලයකි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('5c55d2c9-120e-4bf2-9bda-c397ea411803', '4ae9a879-e58e-5643-ae4c-7db9aa08539b', 'එහි කුහරය පක්ෂ්මධර අපිච්ඡදයකින් ආස්තරණය වේ.', 'එහි කුහරය පක්ෂ්මධර අපිච්ඡදයකින් ආස්තරණය වේ.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('156228e1-c39c-448f-953a-77df82c7539b', '4ae9a879-e58e-5643-ae4c-7db9aa08539b', 'එය ඩිම්බය ඩිම්බකෝෂයේ සිට ගර්භාෂය දක්වා ප්‍රචාලනය කරයි.', 'එය ඩිම්බය ඩිම්බකෝෂයේ සිට ගර්භාෂය දක්වා ප්‍රචාලනය කරයි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('10e55d26-510f-426b-b153-e15412ea952e', '4ae9a879-e58e-5643-ae4c-7db9aa08539b', 'එහි ස්‍රාවයන් ඩිම්බය සහ ශුක්‍රාණු යන දෙකම පෝෂණය කරයි.', 'එහි ස්‍රාවයන් ඩිම්බය සහ ශුක්‍රාණු යන දෙකම පෝෂණය කරයි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('08af44d5-c9c8-474c-8693-06f7deb977cf', '4ae9a879-e58e-5643-ae4c-7db9aa08539b', 'සංසේචනය සාමාන්‍යයෙන් සිදු වන්නේ එහි පහළ $\frac{1}{3}$ ප්‍රදේශයේදී ය.', 'සංසේචනය සාමාන්‍යයෙන් සිදු වන්නේ එහි පහළ $\frac{1}{3}$ ප්‍රදේශයේදී ය.', NULL, 'sanitized', 'v1', 4, 0);
