INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8e0da7bd-fe31-41e3-a064-c37335148321', 'f5c91bb6-45dd-5498-a085-b16eea4220ca', 'මාස 10ක් වයස් වන විට ළදරුවාට පවුලේ අනෙක් සාමාජිකයන් ගන්නා ආහාර ලබා දිය යුතු ය.', 'මාස 10ක් වයස් වන විට ළදරුවාට පවුලේ අනෙක් සාමාජිකයන් ගන්නා ආහාර ලබා දිය යුතු ය.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('fd2822c6-3e09-5b5f-8054-d2930978ff72', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 28, '<p>සමහර මල් දිවා කාලයේදී පිපීම සහ රාත්‍රියේදී හැකිලීම</p>', '<p>සමහර මල් දිවා කාලයේදී පිපීම සහ රාත්‍රියේදී හැකිලීම</p>', NULL, 'දිවා-රාත්‍රී ආලෝක සහ උෂ්ණත්ව වෙනස්වීම් මත ශාක පත්‍ර හෝ පුෂ්ප වල සිදුවන ආවර්තිතා චලන නිද්‍රාසන්නමන චලන (Nyctinastic movements) ලෙස හැඳින්වේ.', 'දිවා-රාත්‍රී ආලෝක සහ උෂ්ණත්ව වෙනස්වීම් මත ශාක පත්‍ර හෝ පුෂ්ප වල සිදුවන ආවර්තිතා චලන නිද්‍රාසන්නමන චලන (Nyctinastic movements) ලෙස හැඳින්වේ.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c7c4b415-6785-44d0-bf7e-11423e28975e', 'fd2822c6-3e09-5b5f-8054-d2930978ff72', 'සාර්වසර චලනයකට නිදසුනකි.', 'සාර්වසර චලනයකට නිදසුනකි.', NULL, 'sanitized', 'v1', 0, 1);
