INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7787aa24-479c-4149-b58e-8becaab4971c', 'fd2822c6-3e09-5b5f-8054-d2930978ff72', 'නිද්‍රාසන්නමන චලනයකට නිදසුනකි.', 'නිද්‍රාසන්නමන චලනයකට නිදසුනකි.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('6f114e6a-2f4a-4107-8c70-3a5cdcd739e8', 'fd2822c6-3e09-5b5f-8054-d2930978ff72', 'ප්‍රභාවර්තී චලනයකට නිදසුනකි.', 'ප්‍රභාවර්තී චලනයකට නිදසුනකි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('b69e5f74-b882-4606-bc36-532d6b9bcc21', 'fd2822c6-3e09-5b5f-8054-d2930978ff72', 'ස්පර්ශාවර්තී චලනයකට නිදසුනකි.', 'ස්පර්ශාවර්තී චලනයකට නිදසුනකි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('b1e0fc35-f4c5-57f3-8ba7-ddfc21da0d92', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 29, '<p>ශාක පටක රෝපණය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් වැරදි වන්නේ කුමක්ද?</p>', '<p>ශාක පටක රෝපණය පිළිබඳ පහත සඳහන් ප්‍රකාශ අතුරෙන් වැරදි වන්නේ කුමක්ද?</p>', NULL, 'ශාක පටක රෝපණයේදී භාවිත කරන්නේ IAA පමණක් අඩංගු මාධ්‍යයක් නොවේ. එහිදී අවශ්‍යතාව අනුව විවිධ වර්ධකයාමක (ඔක්සින් සහ සයිටොකයින් වැනි) සංකලනයන් භාවිත කරයි. එබැවින් පළමු ප්‍රකාශය පටු හා සීමිත අර්ථ දැක්වීමක් වන නිසා එය වැරදි ප්‍රකාශයයි.', 'ශාක පටක රෝපණයේදී භාවිත කරන්නේ IAA පමණක් අඩංගු මාධ්‍යයක් නොවේ. එහිදී අවශ්‍යතාව අනුව විවිධ වර්ධකයාමක (ඔක්සින් සහ සයිටොකයින් වැනි) සංකලනයන් භාවිත කරයි. එබැවින් පළමු ප්‍රකාශය පටු හා සීමිත අර්ථ දැක්වීමක් වන නිසා එය වැරදි ප්‍රකාශයයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('42765fbe-92cb-4431-b970-41c73f21caf4', 'b1e0fc35-f4c5-57f3-8ba7-ddfc21da0d92', 'ශාක පටක රෝපණය යනු IAA සහිත, ජීවාණුහරණය කරන ලද රෝපණ මාධ්‍ය තුළ, නාලස්ථ තත්ත්ව යටතේ ශාක පටක වර්ධනය කිරීමයි.', 'ශාක පටක රෝපණය යනු IAA සහිත, ජීවාණුහරණය කරන ලද රෝපණ මාධ්‍ය තුළ, නාලස්ථ තත්ත්ව යටතේ ශාක පටක වර්ධනය කිරීමයි.', NULL, 'sanitized', 'v1', 0, 1);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('8ef3bbf2-1eab-4eae-a3f7-2600867146fa', 'b1e0fc35-f4c5-57f3-8ba7-ddfc21da0d92', 'බොහෝ ශාක සෛලවලට සුදුසු තත්ත්ව ලබා දුන් විට පූර්ණ ශාකයක් ජනනය කිරීමේ හැකියාව ඇත.', 'බොහෝ ශාක සෛලවලට සුදුසු තත්ත්ව ලබා දුන් විට පූර්ණ ශාකයක් ජනනය කිරීමේ හැකියාව ඇත.', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('be729325-1661-48a3-8a00-54aee1ed274d', 'b1e0fc35-f4c5-57f3-8ba7-ddfc21da0d92', 'පටක රෝපණය ආරම්භ කිරීම සඳහා පූර්වක ලෙස ශාකයක විවිධ කොටස් හෝ පටක හෝ භාවිත කළ හැකි ය.', 'පටක රෝපණය ආරම්භ කිරීම සඳහා පූර්වක ලෙස ශාකයක විවිධ කොටස් හෝ පටක හෝ භාවිත කළ හැකි ය.', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('32e3856b-6d3c-4c78-a6e7-b9d979d2c507', 'b1e0fc35-f4c5-57f3-8ba7-ddfc21da0d92', 'කිණකය යනු පටක රෝපණයේදී පූර්වකයෙන් නිපදවනු ලබන, විභාජනය වන, විභේදනය නොවූ සෛල ගොනුවකි.', 'කිණකය යනු පටක රෝපණයේදී පූර්වකයෙන් නිපදවනු ලබන, විභාජනය වන, විභේදනය නොවූ සෛල ගොනුවකි.', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('26c16f3f-42d7-4e56-9fa6-33119f080c15', 'b1e0fc35-f4c5-57f3-8ba7-ddfc21da0d92', 'පටක රෝපණයේ වාසියක් වන්නේ එකම ප්‍රවේණිදර්ශය සහිත ශාක විශාල සංඛ්‍යාවක් කුඩා ඉඩක ඉක්මනින් නිපදවා ගැනීමයි.', 'පටක රෝපණයේ වාසියක් වන්නේ එකම ප්‍රවේණිදර්ශය සහිත ශාක විශාල සංඛ්‍යාවක් කුඩා ඉඩක ඉක්මනින් නිපදවා ගැනීමයි.', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('88a0efb4-13d5-51a0-a2c9-484305620453', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 30, '<p>පහත සඳහන් ලක්ෂණ අතුරෙන් ඊට ඉදිරියෙන් දක්වා ඇති ශාකයේ දක්නට නොලැබෙන්නේ කුමක්ද?</p>', '<p>පහත සඳහන් ලක්ෂණ අතුරෙන් ඊට ඉදිරියෙන් දක්වා ඇති ශාකයේ දක්නට නොලැබෙන්නේ කුමක්ද?</p>', NULL, 'Solanum (අර්තාපල් වැනි) ශාකවල ආහාර සංචිත කරමින් භූගත කඳේ කෙළවර මහත් වී ආල කන්ද (tuber) සාදයි, එය තිරස් ලෙස දිගට වැඩෙන භූගත කඳක් (rhizome - රයිසෝමයක්) ලෙස සැලකිය නොහැක.', 'Solanum (අර්තාපල් වැනි) ශාකවල ආහාර සංචිත කරමින් භූගත කඳේ කෙළවර මහත් වී ආල කන්ද (tuber) සාදයි, එය තිරස් ලෙස දිගට වැඩෙන භූගත කඳක් (rhizome - රයිසෝමයක්) ලෙස සැලකිය නොහැක.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
