INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('ca3458b5-6840-4fb3-8c24-7e9cc885a1f5', '88a0efb4-13d5-51a0-a2c9-484305620453', 'වායව ප්‍රරෝහ සහිත සිරස් ලෙස වැඩෙන, කෙටි ප්‍රසාරණය වූ භූගත කඳ - Colocasia', 'වායව ප්‍රරෝහ සහිත සිරස් ලෙස වැඩෙන, කෙටි ප්‍රසාරණය වූ භූගත කඳ - Colocasia', NULL, 'sanitized', 'v1', 1, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('c555687a-f947-46ad-beb4-dc68db5b586e', '88a0efb4-13d5-51a0-a2c9-484305620453', 'සිරස් කඳේ කක්ෂීය අංකුරවලින් පැන නගින, තිරස්ව වැඩෙන පාර්ශ්වික ශාඛා - Centella', 'සිරස් කඳේ කක්ෂීය අංකුරවලින් පැන නගින, තිරස්ව වැඩෙන පාර්ශ්වික ශාඛා - Centella', NULL, 'sanitized', 'v1', 2, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('7edb5c5e-6b83-4215-9059-0b5a71d0fe7b', '88a0efb4-13d5-51a0-a2c9-484305620453', 'වායව කඳේ කක්ෂීය අංකුරවලින් හට ගැනෙන, පත්‍ර සහිත කුඩා ප්‍රරෝහ ප්‍රධාන කඳෙන් වෙන් වී නව ශාක ඇති කිරීම - Dioscorea', 'වායව කඳේ කක්ෂීය අංකුරවලින් හට ගැනෙන, පත්‍ර සහිත කුඩා ප්‍රරෝහ ප්‍රධාන කඳෙන් වෙන් වී නව ශාක ඇති කිරීම - Dioscorea', NULL, 'sanitized', 'v1', 3, 0);
INSERT INTO question_options (id, question_id, option_html_en, option_html_si, option_html_ta, sanitization_status, sanitizer_version, sort_order, is_correct) VALUES ('4442dccf-4198-4fac-bdae-5b5560da3dbf', '88a0efb4-13d5-51a0-a2c9-484305620453', 'කඳ හැර වෙනත් වර්ධක කොටස්වලින් අංකුර හට ගැනීම - Bryophyllum', 'කඳ හැර වෙනත් වර්ධක කොටස්වලින් අංකුර හට ගැනීම - Bryophyllum', NULL, 'sanitized', 'v1', 4, 0);
INSERT INTO questions (id, paper_id, number, question_html_en, question_html_si, question_html_ta, explanation_html_en, explanation_html_si, explanation_html_ta, sanitization_status, sanitizer_version, option_count, answer_mode, is_all_correct, marks, marks_source, state, updated_at) VALUES ('21c9915e-0b5e-5255-8579-46b3db9c508e', 'b1dcad4a-2e80-556b-b7c4-1d10c6b5eb3e', 31, '<p>සීමා එන්ඩොනියුක්ලියේස් එන්සයිමවලට හැකියාව ඇත්තේ</p>', '<p>සීමා එන්ඩොනියුක්ලියේස් එන්සයිමවලට හැකියාව ඇත්තේ</p>', NULL, 'සීමා එන්ඩොනියුක්ලියේස් (Restriction endonucleases) එන්සයිම මගින් DNA අණුවක ඇති නිශ්චිත භෂ්ම අනුක්‍රම (recognition sites) හඳුනාගෙන එම විශිෂ්ට ස්ථානවලදී DNA කැපීම සිදු කරයි.', 'සීමා එන්ඩොනියුක්ලියේස් (Restriction endonucleases) එන්සයිම මගින් DNA අණුවක ඇති නිශ්චිත භෂ්ම අනුක්‍රම (recognition sites) හඳුනාගෙන එම විශිෂ්ට ස්ථානවලදී DNA කැපීම සිදු කරයි.', NULL, 'sanitized', 'v1', 5, 'single', 0, 1, 'admin', 'draft', strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(id) DO UPDATE SET paper_id = excluded.paper_id, number = excluded.number, question_html_en = excluded.question_html_en, question_html_si = excluded.question_html_si, explanation_html_en = excluded.explanation_html_en, explanation_html_si = excluded.explanation_html_si, sanitization_status = excluded.sanitization_status, option_count = excluded.option_count, answer_mode = excluded.answer_mode, is_all_correct = excluded.is_all_correct, state = 'draft', updated_at = excluded.updated_at;
